import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-d1-001","clusterId":"D","werkstueckRef":"D.1.1","stufe":2,"question":"Was ist an diesem Einwand der Kern des Denkfehlers, und was wäre der bessere nächste Schritt?","scenario":"In einer Diskussion über den Klimawandel sagt jemand: „Die Studie, die du zitierst, wurde von einem Ölkonzern finanziert. Damit ist sie wertlos.“ Die Studie selbst hat er nicht gelesen.","options":["Er schließt allein aus der Finanzierung, dass die Daten falsch sind. Besser: die Geldgeber als Anlass für besonders genaues Hinsehen nehmen und Methode und Daten der Studie selbst prüfen.","Er schließt aus der möglichen Parteilichkeit der Geldgeber, dass die Ergebnisse zwangsläufig stimmen. Besser: die Studie ungeprüft akzeptieren, solange keine Fälschung nachgewiesen ist.","Er stellt überhaupt die Frage nach den Geldgebern, und das ist in jeder sachlichen Debatte unzulässig. Besser: Finanzierung und Interessen nie zum Thema machen.","Er schließt aus der offengelegten Finanzierung, dass die Studie geprüft und damit verlässlich ist. Besser: Die Offenlegung der Geldgeber als ausreichende Qualitätskontrolle behandeln."],"correctIndex":0,"explanation":"Wer bezahlt, kann ein Motiv für verzerrte Ergebnisse sein. Das ist ein guter Grund, die Studie besonders kritisch zu lesen, etwa auf Methodik, Datenlage und unabhängige Replikation zu achten. Ob die Daten falsch sind, folgt daraus aber nicht: Die Geldgeber sagen etwas über mögliche Interessen, nicht über die Richtigkeit der Messwerte. Zum Fehlschluss wird der Einwand, sobald die Frage nach der Finanzierung die Prüfung der Studie selbst ersetzt, statt sie zu ergänzen. Umgekehrt wäre es genauso falsch, die Frage nach den Geldgebern zu verbieten oder die Studie ungeprüft zu glauben.","coreRule":"⚡ Wer bezahlt, ist ein Grund zum Genauhinsehen – ein Gegenbeweis ist es nicht.","beleg":"Werkstück D.1.1 (Formen des Ad-hominem-Angriffs: interessenbasiert; Der Kipppunkt)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer zahlt, kann ein Motiv für Verzerrung haben, und das ist ein guter Grund, genauer hinzusehen. Der Fehler beginnt, wo die Frage nach den Geldgebern die Prüfung von Methode und Daten ersetzt, statt sie zu ergänzen.","prueffrage":"Hat der Sprecher irgendetwas am Inhalt der Studie beanstandet, oder stützt sich sein ganzer Einwand auf den Geldgeber?","rueckmeldung":[{"option":1,"text":"Die Umkehrung ist genauso unbelegt: Aus einem möglichen Interesse der Geldgeber folgt weder, dass die Ergebnisse falsch sind, noch dass sie stimmen. Die Studie ungeprüft zu glauben, ersetzt die Prüfung ebenfalls durch ein Urteil."},{"option":2,"text":"Nach den Geldgebern zu fragen ist nicht der Fehler, denn mögliche Interessen sind ein guter Grund für genaueres Hinsehen. Falsch wird es erst, wenn diese Frage die Prüfung von Methode und Daten ersetzt."},{"option":3,"text":"Offenlegung macht mögliche Interessen sichtbar, prüft aber nichts: Eine Studie wird durch bloße Transparenz weder geprüft noch verlässlich. Sie ist ein Anlass, Methode und Daten anzusehen, kein Ersatz dafür."}],"familie":"inhalt-statt-absender","fertigkeit":"F2"},{"id":"qx-d1-002","clusterId":"D","werkstueckRef":"D.1.1","stufe":1,"question":"Welche Antwort bleibt beim Argument der Chemikerin und weicht nicht auf die Person aus?","scenario":"In einer Online-Diskussion über die Sicherheit eines neuen Haushaltsreinigers antwortet jemand auf den Hinweis einer Chemikerin, der Wirkstoff sei laut Prüfbericht in der üblichen Dosierung unbedenklich.","options":["„Natürlich findest du den Reiniger harmlos, du arbeitest ja für einen Hersteller. Deinem Prüfbericht glaube ich nichts.“","„Lass uns den Prüfbericht gemeinsam ansehen: Wie wurde die Dosierung festgelegt, und welche Testbedingungen wurden verwendet?“","„Du willst mir etwas über Chemie erzählen? Du benutzt zu Hause selbst jede Menge scharfe Putzmittel.“","„Das kannst du einfach nicht beurteilen, so wie du dich hier aufführst. Wer so schreibt, hat keine Ahnung.“"],"correctIndex":1,"explanation":"Ob ein Wirkstoff in der üblichen Dosierung unbedenklich ist, hängt an den Daten und der Methode des Prüfberichts, nicht an der Person, die darauf hinweist. Die Antwort, die nach Dosierung und Testbedingungen fragt, prüft genau das und bleibt bei der Sache. Die Unterstellung, die Chemikerin arbeite für einen Hersteller, greift ihre Umstände an und ersetzt die Prüfung des Arguments; der Prüfbericht wird dabei pauschal abgetan, ohne ihn anzusehen. Der Hinweis auf die scharfen Putzmittel zu Hause ist ein „Du auch“-Vorwurf: Selbst wenn er stimmt, sagt er nichts darüber, ob der Reiniger sicher ist. Die Herabsetzung als Person („hat keine Ahnung“) trifft den Sprecher statt die Behauptung. Die Glaubwürdigkeit einer Quelle zu hinterfragen kann legitim sein, widerlegt das Argument aber nicht automatisch.","coreRule":"⚡ Prüfe, was gesagt wird, nicht, wer es sagt: Beschimpfung, Motivunterstellung und Heuchelei-Vorwurf führen weg von der Sache und hin zur Person.","quote":"Die logische Gültigkeit oder Falschheit eines Arguments hängt niemals von den Eigenschaften der Person ab, die es ausspricht.","quoteLabel":"Merksatz:","beleg":"Werkstück D.1.1 (Kontext & Tiefe: abusive, Tu quoque, circumstantial)","status":"entwurf","kurz":"Ob die Dosierung unbedenklich ist, entscheidet sich an den Daten und der Methode des Prüfberichts, nicht an der Person, die darauf hinweist. Wer nach Dosierung und Testbedingungen fragt, prüft genau das; Angriffe auf die Person lassen das Argument unberührt.","prueffrage":"Worauf bezieht sich die Antwort: auf das, was im Bericht steht, oder auf die Person, die ihn nennt?","rueckmeldung":[{"option":0,"text":"Ein möglicher Interessenkonflikt darf durchaus Thema sein. Hier wird er aber nur unterstellt, und der Bericht wird pauschal abgetan, ohne ihn anzusehen. So bleibt unklar, ob seine Daten tragen."},{"option":2,"text":"Der Hinweis auf die scharfen Putzmittel zu Hause wechselt vom Reiniger zur Person. Selbst wenn er stimmt, sagt er nichts darüber, ob dieser Reiniger in der üblichen Dosierung sicher ist."},{"option":3,"text":"Hier wird die Sprecherin herabgesetzt, statt ihre Aussage zu prüfen. Ob jemand „Ahnung hat“, zeigt sich an Bericht und Daten, nicht an ihrem Auftreten, und davon ist in dieser Antwort keine Rede."}],"familie":"inhalt-statt-absender","fertigkeit":"F2"},{"id":"qx-d1-003","clusterId":"D","werkstueckRef":"D.1.1","stufe":3,"question":"Welche Reaktion ist die sachlich richtige Antwort auf diese Lage?","options":["Die Finanzierung ist ein Grund, die Studie besonders genau zu prüfen, aber ob die Daten stimmen, zeigt erst die Analyse von Methode und Ergebnissen.","Die Finanzierung ist ohne Belang, denn Daten sind Daten, und deshalb braucht die Studie keine genauere Prüfung als jede andere.","Der Einwand ist berechtigt und beendet die Debatte, denn bei einem belegten Interessenkonflikt sind die Aussagen der Quelle widerlegt.","Die Studie ist nur dann anzuzweifeln, wenn der Wissenschaftlerin Betrug nachgewiesen wird, denn die Finanzierung allein rechtfertigt keine genauere Prüfung."],"correctIndex":0,"explanation":"Motive und Geldgeber zu prüfen ist legitim: Sie sind ein guter Grund für besonders kritisches Lesen. Zum Fehlschluss wird es, wenn diese Prüfung die Auseinandersetzung mit dem Argument ersetzt. Ein Interessenkonflikt beweist nicht, dass die Daten falsch sind. Das zeigt sich nur an der Analyse der Studie selbst: Ist das Argument in sich stimmig, und wird es von Beweisen gestützt? Beide Extreme scheitern: Wer die Finanzierung ignoriert, verschenkt eine wichtige Information, und wer sie als Beweis nimmt, urteilt über die Person statt über die Sache.","coreRule":"⚡ Die Glaubwürdigkeitsprüfung ergänzt die Prüfung des Arguments, sie ersetzt sie nie.","beleg":"Werkstück D.1.1 (Der Kipppunkt; Das Adaptive Talent)","status":"entwurf","scenario":"In einer Diskussion über ein neues Pflanzenschutzmittel stellt eine Wissenschaftlerin Studiendaten vor, nach denen das Mittel unbedenklich ist. Du erfährst, dass ihr Institut vom Hersteller finanziert wird. Ein Teilnehmer ruft: „Die Studie ist damit erledigt, die Frau ist ja gekauft!“","kurz":"Ein Geldgeber mit Interessen ist ein guter Grund, die Studie besonders genau zu lesen. Ob die Daten stimmen, zeigt aber erst die Analyse von Methode und Ergebnissen; „gekauft“ ersetzt diese Prüfung nur durch ein Urteil über die Person.","prueffrage":"Worauf stützt der Teilnehmer sein Urteil „erledigt“: auf etwas in den Daten oder allein auf den Geldgeber?","rueckmeldung":[{"option":1,"text":"Dass Daten nicht schon wegen des Geldgebers falsch sind, stimmt. Trotzdem ist die Finanzierung eine wichtige Information, die man nicht ignorieren sollte, sondern zum Anlass für besonders genaues Lesen nimmt."},{"option":2,"text":"Der Interessenkonflikt ist ein berechtigter Hinweis, widerlegt aber nichts. Ob die Daten stimmen, entscheidet sich an Methode und Ergebnissen der Studie. Ein Urteil über die Quelle beendet die Debatte deshalb nicht."},{"option":3,"text":"Der Schluss „gekauft, also falsch“ trägt tatsächlich nicht. Ein Betrugsnachweis ist für genaueres Prüfen aber nicht nötig: Schon der mögliche Interessenkonflikt ist ein legitimer Grund, die Studie besonders kritisch zu lesen."}],"familie":"inhalt-statt-absender","fertigkeit":"F2"},{"id":"qx-d1-004","clusterId":"D","werkstueckRef":"D.1.1","stufe":4,"question":"Was ist an deiner Folgerung das Problem?","scenario":"Dein Bekannter sagt: „Schau dir diesen heißen Sommer an – der Klimawandel ist real!“ Du antwortest: „Das ist Wetter, nicht Klima – also ist wohl nichts dran an der Erwärmung.“","options":["Nichts: Wer einen Fehler im Argument nachweist, hat damit gezeigt, dass die behauptete Schlussfolgerung falsch ist.","Dein Hinweis ist selbst falsch: Wetter und Klima zu verwechseln ist eine zulässige Abkürzung und kein Denkfehler.","Dein Hinweis ist selbst ein Fehlschluss: Wer einem Argument ein Etikett anheftet, ohne es zu begründen, widerlegt damit nichts.","Dein Hinweis trifft nur das Argument: Ein Fehler darin macht die Behauptung des Bekannten nicht automatisch falsch."],"correctIndex":3,"explanation":"Der Bekannte verwechselt Wetter und Klima, sein Argument ist also fehlerhaft. Ein fehlerhaftes Argument stützt seine Behauptung nicht, aber es widerlegt sie auch nicht: Ob eine Behauptung stimmt, hängt von der Sache und den Belegen ab, nicht davon, wer sie vorbringt oder wie schlecht das Argument dafür gebaut ist. Ob sie stimmt, zeigt erst die Prüfung der Sache selbst, etwa langjährige Temperaturreihen statt eines einzelnen Sommers. Wer aus dem Fehler schließt, an der Erwärmung sei nichts dran, springt zu früh. Dein Hinweis auf die Verwechslung ist berechtigt, aber er beantwortet nur die Frage, ob das Argument taugt, nicht die Frage, ob die Behauptung stimmt.","coreRule":"⚡ Ein Fehler im Argument widerlegt nicht die Behauptung – prüfe die Sache selbst.","beleg":"Werkstück D.1.1 (Ad Hominem), Abschnitte „Kontext & Tiefe“ und „Der Kipppunkt“; keine Fußnote","status":"entwurf","kurz":"Der Hinweis auf die Verwechslung von Wetter und Klima ist berechtigt, trifft aber nur das Argument. Dass ein Argument schlecht ist, macht die Behauptung nicht falsch: Sie kann trotzdem stimmen, und das zeigt erst die Prüfung der Sache selbst.","prueffrage":"Was sagen langjährige Temperaturreihen, wenn du sie neben diesen einen Sommer legst?","rueckmeldung":[{"option":0,"text":"Einen Fehler im Argument zu finden, fühlt sich wie eine Widerlegung an. Er zeigt aber nur, dass dieser Grund nicht trägt. Die Behauptung kann aus einem schlechten Grund vorgebracht werden und trotzdem stimmen."},{"option":1,"text":"Hier liegt die Abkürzung nahe, weil beides mit dem Himmel über uns zu tun hat. Dein Hinweis ist aber berechtigt: Ein einzelner heißer Sommer ist Wetter, Klima meint langfristige Entwicklungen. Das Problem liegt im Schluss, den du daraus ziehst."},{"option":2,"text":"Ein bloßes Etikett widerlegt tatsächlich nichts. Dein Hinweis ist aber keines, sondern begründet: Ein einzelner Sommer sagt über das Klima wenig. Das Problem liegt beim Schluss auf die Erwärmung, nicht beim Hinweis selbst."}],"familie":"fehlschluss-macht-nichts-falsch","fertigkeit":"F2"},{"id":"qx-d1-005","clusterId":"D","werkstueckRef":"D.1.2","stufe":1,"question":"Welche Antwort prüft am besten, ob die Erwiderung deines Bruders deinen Vorschlag trifft?","scenario":"Du sagst beim Familienessen: „Ich fände es schön, wenn wir abends ab und zu ohne Handys essen.“ Dein Bruder erwidert: „Du willst uns also das Handy verbieten und alle zurück in die Steinzeit schicken?“","options":["Ich würde fragen: „Habe ich ein Verbot gefordert?“ Damit lege ich meinen tatsächlichen Satz neben seine Version und vergleiche beide.","Ich würde fragen: „Wie viele Familien auf der Welt essen eigentlich ohne Handy?“ Damit finde ich heraus, ob mein Vorschlag üblich ist und deshalb ernst genommen werden sollte.","Ich würde fragen: „Nutzt du dein Handy beim Essen nicht selbst ständig?“ Damit zeige ich, dass er kein Recht hat, meinen Vorschlag zu bewerten.","Ich würde fragen: „Wo soll das enden, wenn beim Essen jeder nur noch aufs Handy schaut?“ Damit mache ich deutlich, dass seine Haltung das Familienleben auf Dauer verschlechtert."],"correctIndex":0,"explanation":"Aus „ab und zu ohne Handys essen“ macht dein Bruder „Handy verbieten“ und „zurück in die Steinzeit“. Er widerlegt damit nicht deinen Vorschlag, sondern eine übertriebene Version davon: ein Strohmann. Am besten prüfst du das, indem du deinen Satz wörtlich neben seine Wiedergabe legst und fragst, ob sie zusammenpassen. So wird sichtbar, dass er auf etwas antwortet, das du nicht gesagt hast. Die übrigen Fragen prüfen nicht, ob seine Wiedergabe zu deinem tatsächlichen Satz passt. Dein Vorschlag bleibt dabei ungeprüft.","coreRule":"⚡ Prüfe, ob widerlegt wird, was gesagt wurde, oder nur, was sich bequem widerlegen lässt.","quote":"Du fühlst den Drang zu sagen: „Aber das habe ich doch gar nicht gesagt!“","quoteLabel":"Merksatz:","beleg":"Werkstück D.1.2 (Kernidee; Formen des Strohmanns: Übertreibung; Red Flags)","status":"entwurf","kurz":"Dein Bruder antwortet auf eine übertriebene Fassung, nicht auf deinen Satz. Das zeigt sich, wenn du „ab und zu ohne Handys essen“ wörtlich neben „verbieten“ und „Steinzeit“ legst: Ein Verbot hast du nie gefordert.","prueffrage":"Welche Abende und wie viele Mahlzeiten wären von deinem Vorschlag überhaupt betroffen?","rueckmeldung":[{"option":1,"text":"Wie üblich etwas ist, sagt wenig über den Wert deines Vorschlags und gar nichts darüber, ob dein Bruder ihn richtig wiedergegeben hat. Gerade das bleibt so ungeprüft."},{"option":2,"text":"Ob er selbst am Handy hängt, kann für das Gespräch eine Rolle spielen. Es klärt aber nicht, ob er dich richtig zitiert, und jeder darf einen Vorschlag bewerten, auch ohne ihn selbst zu leben."},{"option":3,"text":"Ein Ausblick auf düstere Folgen kann deinen Wunsch dringlicher wirken lassen. Ob dein Bruder deinen Satz richtig wiedergegeben hat, klärt er aber nicht: Über „verbieten“ und „Steinzeit“ sagt diese Frage nichts."}],"familie":"strohmann-erkennen","fertigkeit":"F2"},{"id":"qx-d1-006","clusterId":"D","werkstueckRef":"D.1.2","stufe":2,"question":"Welche Rückfrage prüft am besten, ob dieser Text eine tragfähige Begründung für die Methode liefert?","scenario":"In einem Werbetext für eine alternative Methode steht: „Die Schulmedizin sieht den Menschen nur als Maschine und interessiert sich nicht für die Seele. Wir dagegen behandeln den ganzen Menschen.“ Eine Leserin findet den Text überzeugend und überlegt, die Methode auszuprobieren.","options":["Ob die Schulmedizin so arbeitet, wie der Text behauptet, und was für die eigene Methode belegt wird","Wie viele Menschen den Text gelesen haben und ob sie die Methode später selbst ausprobiert haben","Wie lange es die Methode schon gibt und wer sie vor vielen Jahren ursprünglich entwickelt hat","Welche Berufsgruppe den Text verfasst hat und ob sie am Verkauf der Methode etwas verdient"],"correctIndex":0,"explanation":"Der Text baut ein Zerrbild der Schulmedizin auf und widerlegt dann dieses Zerrbild: Er ignoriert die umfangreiche psychosomatische Forschung und die Bemühungen vieler Ärzte um eine ganzheitliche Betrachtung, um die eigene „alternative“ Methode als einzig empathische darzustellen. Das ist ein Strohmann-Argument. Daraus folgt für die Leserin: Auch ein widerlegtes Zerrbild sagt noch nichts darüber, ob die eigene Methode wirkt. Die richtige Rückfrage prüft deshalb beides: ob die Darstellung des Gegners fair ist und ob für die eigene Methode überhaupt etwas belegt wird. Die anderen Fragen betreffen Beliebtheit, Alter, Herkunft oder Interessen und lassen offen, ob die Methode wirkt.","coreRule":"⚡ Wer die Gegenseite nur als Zerrbild zeigt, hat über die eigene Sache noch nichts bewiesen.","beleg":"Werkstück D.1.2 (Anwendung & Relevanz: In der Pseudomedizin)","status":"entwurf","kurz":"Der Text widerlegt nur ein Zerrbild der Schulmedizin, und das sagt noch nichts darüber, ob die eigene Methode wirkt. Deshalb muss man beides prüfen: ob der Gegner fair dargestellt ist und ob für die Methode selbst etwas belegt wird.","prueffrage":"Wie viele Sätze des Textes handeln von der Schulmedizin, und wie viele davon, was die angebotene Methode bewirkt?","rueckmeldung":[{"option":1,"text":"Viele Leser und Ausprobierer wirken wie ein gutes Zeichen. Die Zahl sagt aber nur, wie bekannt oder beliebt der Text ist, nicht, ob die Begründung trägt oder die Methode wirkt."},{"option":2,"text":"Eine lange Geschichte wirkt vertrauenswürdig, weil sich Dinge ja bewähren könnten. Wie alt eine Methode ist und wer sie erfand, sagt aber nichts darüber, ob sie wirkt oder ob der Text fair argumentiert."},{"option":3,"text":"Wer am Verkauf verdient, hat einen Anreiz zu übertreiben, und das ist ein berechtigtes Warnsignal. Es betrifft aber nur die Quelle: Der Fehler im Text, das verzerrte Bild des Gegners, bleibt dabei unbeachtet."}],"familie":"strohmann-erkennen","fertigkeit":"F2"},{"id":"qx-d1-007","clusterId":"D","werkstueckRef":"D.1.2","stufe":3,"question":"Wie reagierst du am klügsten?","scenario":"In der Teambesprechung schlägst du vor, die Wochenberichte um eine Seite zu kürzen. Ein Kollege ruft: „Du willst also jede Dokumentation abschaffen!“ Mehrere im Raum nicken, die Stimmung kippt.","options":["Seine Behauptung ausführlich widerlegen und belegen, dass Dokumentation wichtig ist, bevor du zu deinem Vorschlag zurückkehrst.","Kurz wiedergeben, wie du ihn verstanden hast, und dann sagen, was du tatsächlich vorgeschlagen hast.","Ihm im selben Ton eine überzogene Version seiner eigenen Position entgegenhalten, damit beide gleich dastehen.","Zunächst schweigen und warten, bis die anderen den Fehler von selbst bemerken, damit du nicht in die Defensive gerätst."],"correctIndex":1,"explanation":"Der Kollege hat nicht auf deinen Vorschlag geantwortet, sondern auf eine übertriebene Fassung davon: ein Strohmann. Am wirksamsten ist es, die Verzerrung sichtbar zu machen und die Debatte zu deiner tatsächlichen Aussage zurückzuführen. Das gelingt, wenn du seine Fassung neutral zurückspiegelst und deinen Punkt klarstellst. Oft reicht diese sanfte Konfrontation schon, um den Angreifer zum Zurückrudern zu zwingen. Wer die Karikatur ausführlich widerlegt, kämpft auf dem Feld des Gegners und bekämpft eine Position, die nie jemand vertreten hat. Ein Gegen-Strohmann wiederholt nur den Fehler in die andere Richtung. Und wer schweigt, lässt die falsche Darstellung stehen, die der Raum dann als deine Position verbucht.","coreRule":"⚡ Spiegle den Strohmann neutral zurück und führe die Debatte zu deiner tatsächlichen Aussage.","quote":"Das ist eine interessante Kritik, aber sie richtet sich nicht gegen das, was ich gesagt habe. Mein eigentlicher Punkt war...","quoteLabel":"Beispielantwort:","beleg":"Werkstück D.1.2 (Das Anti-Denkmuster: Aktivierungs-Frage)","status":"entwurf","kurz":"Der Kollege hat auf eine übertriebene Fassung deines Vorschlags geantwortet. Wenn du seine Version neutral zurückspiegelst und deinen eigentlichen Punkt klarstellst, wird die Verzerrung sichtbar, und die Debatte kehrt zu dem zurück, was du gesagt hast.","prueffrage":"Beziehen sich die Einwände im Raum auf das, was du gesagt hast, oder auf etwas, das erst danach daraus gemacht wurde?","rueckmeldung":[{"option":0,"text":"Dass Dokumentation wichtig ist, stimmt wohl, und ein klarer Widerspruch wirkt engagiert. Abschaffen wolltest du sie aber nie; eine lange Verteidigung kämpft gegen eine Position, die niemand vertreten hat, und das Gespräch bleibt auf seinem Feld."},{"option":2,"text":"Gleiches mit Gleichem zu vergelten wirkt ausgleichend, weil dann beide überzogen dastehen. Doch auch dein Gegenstück ist eine Karikatur, wiederholt den Fehler in die andere Richtung und bringt die Runde nicht zu deinem eigentlichen Vorschlag zurück."},{"option":3,"text":"Nicht sofort in die Defensive zu gehen ist ein berechtigtes Ziel. Schweigen lässt die verzerrte Darstellung aber stehen, und der Raum verbucht sie womöglich als deine Position, statt den Fehler selbst zu bemerken."}],"familie":"strohmann-erkennen","fertigkeit":"F2"},{"id":"qx-d1-008","clusterId":"D","werkstueckRef":"D.1.2","stufe":4,"question":"Was solltest du tun, bevor du Jonas’ Vorschlag kritisierst, damit du nicht dasselbe tust wie Mara?","scenario":"Kollege Jonas sagt in der Teambesprechung: „Ich würde die Kernarbeitszeit etwas lockern, damit Eltern ihre Kinder morgens in Ruhe in die Kita bringen können.“ Deine Kollegin Mara antwortet empört: „Jonas will also, dass niemand mehr pünktlich im Büro ist und alle kommen und gehen, wann sie wollen!“ Du sollst gleich selbst auf Jonas’ Vorschlag antworten und möchtest dabei fair bleiben.","options":["Jonas’ Vorschlag in seiner stärksten Form zusammenfassen und ihn bestätigen lassen, dass du ihn richtig verstanden hast.","Jonas’ Vorschlag auf seinen schwächsten Punkt prüfen und genau diesen gezielt kritisieren, um das Gespräch zu straffen.","Allgemein über Arbeitszeitmodelle sprechen und Jonas’ Vorschlag erst später im Gespräch konkret behandeln.","Jonas’ Vorschlag mit deiner eigenen Sicht zu einem Kompromiss verschmelzen und erst danach Kritik äußern."],"correctIndex":0,"explanation":"Mara hat nicht auf Jonas’ tatsächlichen Vorschlag geantwortet, sondern eine übertriebene Karikatur davon angegriffen: einen Strohmann. Das Gegenmittel ist die faire Rekonstruktion: Du gibst die Position des anderen in ihrer besten Form wieder und lässt sie bestätigen, bevor du sie kritisierst. Dann kann kein Strohmann entstehen, und deine Kritik trifft den echten Vorschlag. Sich nur den schwächsten Punkt herauszupicken, ähnelt dem „Fokus auf den Rand“, einer Weise, einen Strohmann zu bauen. Über das Thema allgemein zu reden oder sofort einen Kompromiss zu bauen, setzt sich ebenfalls nicht mit dem tatsächlichen Argument auseinander.","coreRule":"⚡ Gib die Position des Gegners in ihrer stärksten Form wieder, bevor du sie kritisierst – dann kann kein Strohmann entstehen.","beleg":"Werkstück D.1.2 (Formen des Strohmanns; Verbindungen: Stahlmann-Argument; Fußnote gl-d-strohmann: Principle of Charity, Bowell/Kemp 2002)","status":"entwurf","kurz":"Maras Antwort greift eine Karikatur an, nicht Jonas’ Vorschlag. Gibst du seine Position erst in ihrer stärksten Form wieder und lässt sie bestätigen, trifft deine Kritik den echten Vorschlag und nicht einen Strohmann.","prueffrage":"Welchen Zweck nennt Jonas, und wie weit soll die Lockerung nach seinen Worten gehen?","rueckmeldung":[{"option":1,"text":"Sich auf den schwächsten Punkt zu stürzen, spart Zeit und fühlt sich gründlich an. Es greift aber nur den Rand heraus und lässt das eigentliche Anliegen liegen. Das ähnelt selbst einem Strohmann."},{"option":2,"text":"Ein allgemeines Gespräch über Arbeitszeitmodelle wirkt sachlich und sicher. Jonas’ konkreter Vorschlag bleibt dabei aber unbesprochen, und Verschieben ist kein Verstehen."},{"option":3,"text":"Ein Kompromiss klingt fair und kooperativ. Er setzt jedoch voraus, dass du Jonas schon richtig verstanden hast, und das ist ungeprüft. Wird sein Vorschlag mit deiner Sicht vermischt, ist er kaum noch erkennbar."}],"familie":"fair-wiedergeben","fertigkeit":"F3"},{"id":"qx-d1-009","clusterId":"D","werkstueckRef":"D.1.3","stufe":2,"question":"Welche Möglichkeit blendet dieser Satz aus?","scenario":"Bei einer Vereinsreform sagt der Vorsitzende: „Wer nicht Teil der Lösung ist, ist Teil des Problems.“ Du hältst den Reformplan für unausgereift, hast aber selbst noch keinen besseren Vorschlag.","options":["Dass die Reform auch ohne dein Zutun beschlossen werden kann und deine Haltung dadurch folgenlos bleibt.","Dass man den Plan kritisieren kann, ohne das Problem zu stützen, etwa weil man ihn erst verbessern will.","Dass der Vorsitzende als Amtsträger auftritt und deshalb jeden Widerspruch im Verein unterbinden möchte.","Dass es im Verein zwei Lager gibt, die man gleichberechtigt anhören müsste, damit beide Seiten ausgewogen vertreten sind."],"correctIndex":1,"explanation":"Der Satz presst die Lage in ein Entweder-oder: Wer den Plan unterstützt, ist Teil der Lösung, wer ihn nicht unterstützt, Teil des Problems. Dabei fällt unter den Tisch, dass man einen Plan für unausgereift halten kann, ohne schon eine bessere Lösung zu haben, etwa weil man ihn erst verbessern oder das Problem genauer verstehen will. Das macht niemanden zum Teil des Problems. Der Fehlschluss heißt falsches Dilemma; er funktioniert, weil Kritik an der einen Seite automatisch als Zustimmung zur anderen gedeutet wird. Ein prüfender Gegenzug ist die Frage: „Welche weiteren Möglichkeiten gibt es neben diesen beiden?“","coreRule":"⚡ Wer nur zwei Plätze anbietet, hat die übrigen Möglichkeiten schon aus dem Raum geschoben.","beleg":"Werkstück D.1.3 (Anwendung & Relevanz: Im Alltag; Red Flags; Anti-Denkmuster)","status":"entwurf","kurz":"Der Satz kennt nur „Teil der Lösung“ und „Teil des Problems“. Wer den Plan kritisiert, kann ihn aber auch erst verbessern oder das Problem genauer verstehen wollen, ohne deshalb Teil des Problems zu sein.","prueffrage":"Was genau stört dich am Reformplan, und was müsste sich ändern, damit du zustimmst?","rueckmeldung":[{"option":0,"text":"Dass die eigene Haltung folgenlos bleiben kann, ist durchaus denkbar. Darum geht es in dem Satz aber nicht: Er stellt nur zwei Positionen zur Wahl und blendet aus, dass man den Plan kritisieren kann, ohne das Problem zu stützen."},{"option":2,"text":"Eine Amtsrolle kann Druck erzeugen, und manchmal soll ein solcher Satz tatsächlich Widerspruch dämpfen. Über die Absichten des Vorsitzenden ist aber nichts bekannt; der Fehler steckt in der Form des Satzes, nicht in vermuteten Motiven."},{"option":3,"text":"Beide Seiten anzuhören klingt fair, übernimmt aber die Zweiteilung, die der Satz vorgibt. Fehlerhaft ist gerade, dass nur zwei Positionen zur Wahl stehen und andere Lösungen oder offene Fragen darin keinen Platz haben."}],"familie":"falsches-dilemma","fertigkeit":"F2"},{"id":"qx-d1-010","clusterId":"D","werkstueckRef":"D.1.3","stufe":3,"question":"Beide Aussagen sind Entweder-oder-Aussagen, aber nur eine davon ist ein Falsches Dilemma. Woran erkennst du, welche?","scenario":"Im Gemeinderat sagt ein Redner zur geplanten Umgehungsstraße: „Entweder bauen wir die Straße genau so, wie sie jetzt geplant ist, oder unser Ort erstickt im Verkehr. Wer dagegen stimmt, will den Stau.“ Auf einem Formular der Gemeinde steht dagegen die Frage: „Wurde die Gebühr bezahlt? Ja oder Nein.“","options":["Daran, ob eine der beiden Optionen unangenehm klingt: Dann liegt ein Falsches Dilemma vor, weil die Wahl unangenehm ist.","Daran, ob der Sprecher eine Entscheidung verlangt: Wer das tut, erzwingt eine Wahl und begeht damit ein Falsches Dilemma.","Daran, ob es weitere Möglichkeiten gibt, die verschwiegen werden: Die Zweiteilung wird dann künstlich aufgezwungen und engt den Denkraum ein.","Daran, ob beide Optionen extrem sind: Wirkt eine Zweiteilung gemäßigt, handelt es sich um eine zulässige Unterscheidung."],"correctIndex":2,"explanation":"Ein echtes Dilemma gibt es nur, wenn tatsächlich nur zwei Möglichkeiten bestehen, etwa bei „Leben oder Tod“. Die Gebühr ist entweder bezahlt oder nicht, das Formular ist also unproblematisch. Beim Redner im Gemeinderat gibt es dagegen mehr Möglichkeiten: Er verschweigt sie, damit seine Variante als einzig vernünftige Wahl erscheint, und stempelt Kritik als Wunsch nach dem Stau ab. Entscheidend ist also nicht die Form „Entweder-oder“, sondern ob es wirklich keine dritte Möglichkeit gibt oder ob sie nur ausgeblendet wird.","coreRule":"⚡ Prüfe nicht die Form „Entweder-oder“, sondern ob es wirklich keine dritte Möglichkeit gibt.","beleg":"Werkstück D.1.3 (Kontext & Tiefe: echtes Dilemma; Der Kipppunkt)","status":"entwurf","kurz":"Eine Zweiteilung ist nur dann ein Falsches Dilemma, wenn es weitere Möglichkeiten gibt, die verschwiegen werden. Die Form „Entweder-oder“ allein ist noch kein Fehler: Eine Gebühr ist wirklich entweder bezahlt oder nicht.","prueffrage":"Was haben beide Aussagen gemeinsam: Verlangen beide eine Entscheidung, und klingt in beiden eine der Möglichkeiten unangenehm?","rueckmeldung":[{"option":0,"text":"Ein unangenehmes „Nein“ im Formular macht die Frage nicht fehlerhaft, denn die Gebühr ist tatsächlich entweder bezahlt oder nicht. Wie es sich anfühlt, sagt nichts darüber, ob eine dritte Möglichkeit existiert."},{"option":1,"text":"Eine Entscheidung zu verlangen ist nicht für sich fehlerhaft, auch das Formular verlangt eine Antwort. Beim Redner ist problematisch, dass er andere Wege ausblendet, nicht dass er eine Wahl fordert."},{"option":3,"text":"Mit Extremen hat der Fehler nur zufällig zu tun: Auch zwei harmlos klingende Optionen können einen dritten Weg verdecken. Eine Zweiteilung ist zulässig, wenn es wirklich nur zwei Möglichkeiten gibt, nicht schon, weil sie gemäßigt wirkt."}],"familie":"falsches-dilemma","fertigkeit":"F2"},{"id":"qx-d1-011","clusterId":"D","werkstueckRef":"D.1.3","stufe":4,"question":"Wie beurteilst du diesen Einwand am besten?","scenario":"In einem Forum wird behauptet: „Bush hat nach dem 11. September 2001 gesagt: ‚Wer nicht für uns ist, ist gegen uns.‘ Das ist ein Lehrbuchbeispiel für ein Falsches Dilemma.“ Ein anderer Nutzer antwortet: „Das Zitat ist so wohl nicht korrekt. Im Transkript der Rede vor dem Kongress vom 20. September 2001 steht: ‚Either you are with us, or you are with the terrorists.‘ Dein Beispiel taugt also nichts.“","options":["Der Einwand betrifft nur den Wortlaut: Auch das Original bietet nur zwei Optionen an, daher bleibt es ein Falsches Dilemma.","Der Einwand widerlegt die Behauptung, denn mit einem ungenauen Zitat ist auch die Einordnung als Falsches Dilemma hinfällig geworden.","Der Einwand ist unerheblich, denn bei einem Beispiel für einen Fehlschluss kommt es nur auf die ungefähre Aussage an, nicht auf den genauen Wortlaut.","Der Einwand zeigt, dass der Originalsatz kein Falsches Dilemma ist, denn „mit den Terroristen“ ist inhaltlich eine andere Aussage als „gegen uns“."],"correctIndex":0,"explanation":"Zwei Dinge müssen getrennt werden: ob das Zitat stimmt und ob die Struktur ein Falsches Dilemma ist. Der Einwand prüft nur die Kongressrede vom 20. September 2001: Laut Transkript lautet der Satz dort „Either you are with us, or you are with the terrorists.“ Dem Forumssatz entspricht aber, was Bush am 6. November 2001 bei einer Pressekonferenz mit Frankreichs Präsident Chirac sagte: „You’re either with us or against us in the fight against terror.“ (so berichtet von CNN). Für die Einordnung kommt es auf den Wortlaut ohnehin nicht an: Beide Sätze bieten nur zwei Möglichkeiten an, eine dritte oder neutrale Haltung ist nicht vorgesehen. Ein ungenaues Zitat macht die Einordnung also nicht falsch, es verlangt nur, das Beispiel am Original zu belegen. Wer Fehlschlüsse benennt, sollte genau zitieren, und wer widerspricht, sollte prüfen, ob der Einwand die Kernaussage überhaupt trifft.","coreRule":"⚡ Prüfe bei einem Einwand, ob er die Struktur des Arguments trifft oder nur ein Detail wie das Zitat, und belege Beispiele am Originalwortlaut.","beleg":"Werkstück D.1.3 (Anwendung & Relevanz: In der Politik); Fn. gl-d-bush911 (Bush, Address to a Joint Session of Congress, 20.09.2001, Transkript des Weißen Hauses). Pressekonferenz mit Chirac, 6.11.2001: CNN, „You are either with us or against us“, https://edition.cnn.com/2001/US/11/06/gen.attack.on.terror/ (abgerufen 12.10.2026); wiedergegeben auch bei Monshipouri (2012): Terrorism, Security, and Human Rights, Lynne Rienner, Anm. 10.","status":"entwurf","kurz":"Der Einwand prüft nur die Kongressrede; einen fast gleichen Satz sagte Bush am 6. November 2001. Und selbst bei falschem Wortlaut bliebe es ein Falsches Dilemma: Auch der Satz der Kongressrede bietet nur zwei Möglichkeiten an.","prueffrage":"Bei welchen Gelegenheiten hat Bush ähnliche Sätze gesagt, und wo steht jeweils der genaue Wortlaut?","rueckmeldung":[{"option":1,"text":"Ein ungenaues Zitat lässt das ganze Beispiel erledigt wirken. Ob eine Aussage nur zwei Möglichkeiten zulässt, zeigt sich aber an ihrer Form, und die steckt auch im Satz der Kongressrede. Nötig ist ein genauer Beleg, nicht das Ende des Beispiels."},{"option":2,"text":"Dass der Kern gleich bleibt, stimmt: Beide Fassungen kennen nur zwei Lager. Genau deshalb lässt sich das Beispiel retten. Daraus folgt aber nicht, dass der Wortlaut egal ist; wer einen Fehlschluss anprangert, muss ihn am echten Satz belegen."},{"option":3,"text":"Die beiden Formulierungen sind tatsächlich nicht gleichbedeutend. Dieser Unterschied ändert aber nichts an der Zweiteilung: Auch „mit uns oder mit den Terroristen“ lässt keinen Platz für eine neutrale oder dritte Haltung."}],"familie":"schluss-pruefen","fertigkeit":"F2"},{"id":"qx-d1-012","clusterId":"D","werkstueckRef":"D.1.4","stufe":1,"question":"Wie solltest du auf das Argument deines Onkels am besten reagieren?","scenario":"Ein berühmter Literatur-Nobelpreisträger erklärt in einem Interview, ein neuer Impfstoff sei unsicher. Dein Onkel meint: „Dem Mann sollte man glauben, er hat schließlich einen Nobelpreis.“ Studien zum Impfstoff kennt dein Onkel nicht.","options":["Du fragst, ob der Preisträger in der Impfstoffforschung Fachwissen hat und welche Daten er vorlegt.","Du fragst, ob der Preisträger sich im Interview sachlich genug ausgedrückt hat, denn nur ein ruhiger Ton macht eine Aussage glaubwürdig.","Du fragst, ob der Preisträger auch von vielen Menschen gelesen wird, denn große Bekanntheit macht eine Aussage über Impfstoffe verlässlich.","Du fragst, ob der Preisträger der Mehrheitsmeinung widerspricht, denn Widerspruch zu den Fachleuten spricht für die Richtigkeit seiner Aussage."],"correctIndex":0,"explanation":"Ein Preis belegt Können nur in dem Fach, in dem er erworben wurde. Wer Literatur auf Weltklasseniveau beherrscht, ist deshalb noch kein Fachmann für Impfstoffe. Ob eine Aussage über einen Impfstoff stimmt, entscheiden Daten aus Studien, nicht der Name dessen, der sie ausspricht. Dein Onkel ersetzt hier den Beweis durch einen Verweis auf eine Person, und zwar auf eine, deren Fachgebiet gar nicht zur Frage passt. Die beste Reaktion fragt deshalb nach Zuständigkeit und nach Belegen. Auch der bloße Widerspruch zum Konsens beweist nichts, denn das wäre der umgekehrte Appell an die Autorität des „Ketzers“.","coreRule":"⚡ Ein Rang beweist nur etwas in dem Fach, in dem er erworben wurde.","quote":"Er ersetzt den **Beweis (die Daten)** durch einen **Verweis (den Experten)**.","quoteLabel":"Merksatz:","beleg":"Werkstück D.1.4 (Kernidee: Hauptformen des Fehlschlusses)","status":"entwurf","kurz":"Ein Preis belegt Können nur in seinem Fach, und über einen Impfstoff entscheiden Studiendaten, nicht der Name des Sprechers. Wer dem Ansehen folgt, ersetzt den Beweis durch eine Person, deren Fachgebiet hier gar nicht passt.","prueffrage":"Wofür wurde der Preis verliehen, und wer hat den Impfstoff bisher in Studien untersucht?","rueckmeldung":[{"option":1,"text":"Ein ruhiger, sachlicher Auftritt kann überzeugend wirken, sagt aber nur etwas über die Form. Ob die Aussage über den Impfstoff stimmt, zeigen erst Daten aus Studien, nicht der Ton, in dem sie vorgetragen wird."},{"option":2,"text":"Wer viel gelesen wird, erreicht viele Menschen, mehr aber nicht. Reichweite ist kein Beleg für Richtigkeit. Auch eine bekannte Stimme ersetzt keine Studien, sie macht die Aussage nur lauter."},{"option":3,"text":"Widerspruch zu den Fachleuten kann Gründe haben, ist aber für sich kein Beleg. Wer Abweichung schon für ein Zeichen von Wahrheit hält, tauscht nur den Verweis auf Autorität gegen einen Verweis auf den „Ketzer“."}],"familie":"autoritaet-pruefen","fertigkeit":"F2"},{"id":"qx-d1-013","clusterId":"D","werkstueckRef":"D.1.4","stufe":2,"question":"Welche Rückfrage bringt die Debatte am besten weiter?","scenario":"In einer Debatte über Vitamin C und Krebs stellst du fest, dass es dafür keine robusten Belege aus kontrollierten Studien gibt. Dein Gegenüber antwortet: „Linus Pauling, ein zweifacher Nobelpreisträger, hat hochdosiertes Vitamin C gegen Krebs vehement vertreten. Willst du es etwa besser wissen als er?“","options":["Wie bekannt ist die Person in der Öffentlichkeit, und wie oft wird sie in Debatten zitiert?","Welche Daten hat die Person vorgelegt, und lassen sich diese in kontrollierten Studien bestätigen?","Wie lange vertritt die Person ihre Meinung schon, und hat sie diese je öffentlich geändert?","Wer hat die Aussage der Person aufgegriffen, und wie weit wurde sie weiterverbreitet?"],"correctIndex":1,"explanation":"Der Einwand setzt eine Person an die Stelle der Daten. Paulings Nobelpreise waren für Chemie (1954) und Frieden (1962), nicht für Medizin. Entscheidend ist, was kontrollierte Studien zeigen: Gegen fortgeschrittenen Krebs half hochdosiertes Vitamin C zum Einnehmen nicht (Moertel u. a. 1985); Infusionen mit weit höheren Blutspiegeln werden noch erforscht. Die beste Antwort lenkt daher von der Person zur Evidenz: Welche Daten gibt es, und halten sie einer Prüfung stand? Man kann jemanden respektieren und trotzdem verlangen, dass die Behauptung durch Daten gedeckt ist.","coreRule":"⚡ Respekt vor der Person ersetzt nicht den Blick auf die Daten.","beleg":"Werkstück D.1.4 (Einstiegsszene); Fn. gl-d-pauling (Nobelstiftung: Chemie 1954, Frieden 1962; Moertel u. a. 1985, NEJM 312(3), S. 137–141; Padayatty u. a. 2004; NCI (Infusionen))","status":"entwurf","kurz":"Entscheidend ist, was kontrollierte Studien zeigen, nicht, wer die Behauptung vertritt. Paulings Nobelpreise gingen an Chemie und Frieden, nicht an Medizin. Der Fehler: Ein berühmter Name wird an die Stelle der Daten gesetzt.","prueffrage":"Wofür genau hat Pauling seine beiden Nobelpreise bekommen?","rueckmeldung":[{"option":0,"text":"Wie bekannt jemand ist und wie oft er zitiert wird, sagt etwas über Reichweite, nicht über Richtigkeit. Auch ein sehr bekannter Name macht die Behauptung nicht wahrer. Die Frage dreht sich weiter um die Person statt um die Daten."},{"option":2,"text":"Wer eine Meinung lange und standhaft vertritt, wirkt überzeugend. Dauer und Vehemenz belegen aber nichts: Auch lange gehaltene Überzeugungen können durch Studien widerlegt werden. Gefragt wird so wieder nach der Person, nicht nach der Evidenz."},{"option":3,"text":"Weite Verbreitung zeigt, dass eine Aussage ankommt, nicht, dass sie stimmt. Auch Irrtümer verbreiten sich weit. Geprüft werden müssen die Daten, nicht, wie weit die Botschaft gekommen ist."}],"familie":"autoritaet-pruefen","fertigkeit":"F2"},{"id":"qx-d1-014","clusterId":"D","werkstueckRef":"D.1.4","stufe":3,"question":"Ist dein Vertrauen in Hausarzt und Pilotin schon derselbe Fehler wie das Argument deines Bekannten, und wo liegt der Unterschied?","scenario":"Du lässt dich vom Hausarzt beraten, ohne sein Diplom zu prüfen, und vertraust der Pilotin, ohne ihre Lizenz zu kontrollieren. Später verteidigt ein Bekannter eine Gesundheitsbehauptung mit dem Satz: „Der Mann ist Professor, wer bist du, das zu bezweifeln?“ Dir fällt auf, dass du in beiden Fällen Fachleuten vertraust.","options":["Ja, jedes Vertrauen ohne eigene Prüfung ist ein Fehlschluss, weil man dabei die Evidenz durch eine Person ersetzt.","Nein, der Unterschied liegt darin, dass dein Vertrauen auf Fachleute zielt, die einen guten Ruf haben, sein Argument aber nicht.","Nein, der Fehler beginnt erst, wenn du die Aussage eines Fachmanns durch eine zweite Meinung überprüfst, weil du ihm dann misstraust.","Nein, dein Vertrauen ist eine nützliche Abkürzung; fehlerhaft wird es, sobald die Person als Beweis dient und Nachfragen nach den Belegen verboten werden."],"correctIndex":3,"explanation":"Wir können nicht alles selbst wissen. Vertrauen an (hoffentlich) evidenzbasierte Fachleute zu delegieren ist die Grundlage unserer arbeitsteiligen Gesellschaft. Dein Vertrauen bleibt ein Wegweiser zur Evidenz: Du könntest nachfragen und die Belege würden der Prüfung standhalten. Zum Fehlschluss wird es, wenn die Person an die Stelle der Daten tritt und die Frage „Was weißt du?“ durch „Wer bist du, das zu bezweifeln?“ ersetzt wird. Dann dient die Autorität nicht mehr als Hinweis auf Belege, sondern als Totschlagargument. Eine legitime Expertenmeinung wird dabei zum unfehlbaren Beweis, der jede Nachfrage verbietet (Autorität als Dogma). Reputation ist nicht Evidenz. Entscheidend ist nicht, ob du selbst alles prüfst, sondern ob Nachfragen nach den Belegen erlaubt bleiben.","coreRule":"⚡ Vertrauen in Fachleute ist klug – solange die Frage nach der Evidenz erlaubt bleibt.","quote":"","quoteLabel":"","beleg":"Werkstück D.1.4 (Kontext & Tiefe: Logik vs. Heuristik; Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Vertrauen in Fachleute ist eine sinnvolle Abkürzung, solange du nachfragen könntest und die Belege standhielten. Zum Fehlschluss wird es, wenn die Person die Belege ersetzt und Nachfragen als Anmaßung gelten.","prueffrage":"Woher könntest du erfahren, ob der Rat deines Hausarztes trägt, ohne selbst Medizin studiert zu haben?","rueckmeldung":[{"option":0,"text":"Dass eine Person die Belege ersetzt, ist tatsächlich das Kernproblem. Aber nicht jedes Vertrauen ohne eigene Prüfung tut das: Solange Nachfragen möglich bleiben, ist es eine sinnvolle Arbeitsteilung und kein Fehlschluss."},{"option":1,"text":"Ein guter Ruf kann auf Belege hindeuten, trägt als Unterscheidung aber nicht: Auch der Bekannte beruft sich auf einen Titel. Entscheidend ist, ob die Person zur Evidenz führt oder sie ersetzt und Nachfragen verbietet."},{"option":2,"text":"Eine zweite Meinung einzuholen ist kein Misstrauen, sondern genau das Nachfragen, das gesundes Vertrauen aushält. Fehlerhaft wird es im umgekehrten Fall, wenn Nachfragen unterbunden werden."}],"familie":"autoritaet-pruefen","fertigkeit":"F2"},{"id":"qx-d1-015","clusterId":"D","werkstueckRef":"D.1.4","stufe":4,"question":"Was ist an dieser Begründung fehlerhaft?","scenario":"Im Netz heißt es: „Dr. Müller ist ein mutiger Abtrünniger, den die ‚Mainstream-Wissenschaft‘ mundtot macht. Gerade weil er den Fachleuten widerspricht, müssen seine Thesen stimmen.“","options":["Nichts, weil wer dem Konsens widerspricht, von dessen Interessen unabhängig und damit glaubwürdiger ist.","Nichts, weil Dr. Müller tatsächlich Fachmann in genau dem Gebiet ist, über das er hier spricht.","Sie ersetzt Belege durch die Person, denn Widerspruch allein beweist nichts über die Thesen.","Sie ist ein Zirkelschluss, weil sie Müllers Thesen mit seiner Wahrheitsliebe und diese wiederum mit seinen Thesen begründet."],"correctIndex":2,"explanation":"Auch die Umkehrung des Autoritätsarguments ist ein Fehlschluss: Statt Daten wird die Person des „mutigen Abtrünnigen“ als Beweis angeführt. Dass jemand der Fachgemeinschaft widerspricht, macht seine Thesen weder wahr noch falsch. Entscheidend bleibt, welche Belege er vorlegt und wie die gesamte Fachgemeinschaft sie bewertet.","coreRule":"⚡ Widerspruch zum Konsens ist kein Beweis – auch der Außenseiter braucht Daten.","beleg":"Werkstück D.1.4 (Kontext & Tiefe: Die Autoritäts-Umkehrung; Red Flags)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Dass jemand der Fachwelt widerspricht, sagt nichts darüber, ob seine Thesen stimmen. Der Fehler liegt darin, statt Daten die Rolle des „mutigen Abtrünnigen“ als Beweis zu nehmen; Belege und ihre Bewertung durch die Fachgemeinschaft entscheiden.","prueffrage":"Was erfährst du aus dem Beitrag über den Inhalt von Müllers Thesen?","rueckmeldung":[{"option":0,"text":"Unabhängigkeit von Interessen kann Glaubwürdigkeit stützen. Wer widerspricht, ist aber nicht automatisch unabhängig, und selbst dann ist eine These nicht schon deshalb wahr; es zählt, was belegt ist."},{"option":1,"text":"Über Müllers Fachgebiet sagt der Beitrag nichts, und die Begründung beruft sich auch gar nicht darauf, sondern auf seinen Widerspruch. Selbst Fachleute können irren; entscheidend bleiben Belege."},{"option":3,"text":"Ein Zirkelschluss klingt nach einem passenden Fachbegriff. Von Müllers Wahrheitsliebe ist aber gar nicht die Rede, und nichts stützt sich im Kreis: Aus dem bloßen Widerspruch wird direkt auf die Wahrheit geschlossen, ganz ohne Belege."}],"familie":"autoritaet-pruefen","fertigkeit":"F2"},{"id":"qx-d1-016","clusterId":"D","werkstueckRef":"D.1.5","stufe":1,"question":"Wie bewertest du den Gegenvorwurf deines Mitbewohners im Hinblick auf deine Kritik?","scenario":"Du sprichst deinen Mitbewohner darauf an, dass er ständig Geräte unnötig laufen lässt. Er kontert: „Du lässt doch selbst dauernd das Licht im Flur brennen!“","options":["Er ändert nichts am Kern deiner Kritik, denn ob der Vorwurf an dich stimmt, ist für die Frage seines Stromverbrauchs irrelevant.","Er entkräftet deine Kritik vollständig, denn wer selbst gegen die Regel verstößt, kann sie bei anderen nicht mehr einfordern.","Er entkräftet deine Kritik teilweise, denn ein inkonsequenter Kritiker hat auch das schwächere Argument.","Er macht deine Kritik unbrauchbar, denn du hättest sie zuerst auf dein eigenes Verhalten anwenden müssen."],"correctIndex":0,"explanation":"Das ist ein Tu quoque („du auch“): Ob eine Kritik zutrifft, hängt von ihrer Logik und den Belegen ab, nicht davon, ob der Sprecher selbst konsequent handelt. Ob dein Mitbewohner unnötig Strom verbraucht, entscheidet sich an seinem Verhalten, auch wenn du im Flur das Licht brennen lässt. Dein Licht verdient vielleicht ein eigenes Gespräch, beantwortet aber nicht die Frage, ob er zu viel Strom verbraucht.","coreRule":"⚡ Ob jemand selbst danach lebt, entscheidet nicht, ob seine Aussage stimmt.","quote":"Ein Mörder, der sagt „Morden ist falsch“, hat immer noch Recht.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück D.1.5 (Kernidee; Kontext & Tiefe: Logische Ungültigkeit)","status":"entwurf","kurz":"Ob dein Mitbewohner zu viel Strom verbraucht, zeigt sein eigenes Verhalten, nicht dein Flurlicht. Der Gegenvorwurf misst die Kritik an deiner Konsequenz statt an den Belegen; dein Licht verdient vielleicht ein eigenes Gespräch, beantwortet die Frage aber nicht.","prueffrage":"Welche Geräte lässt dein Mitbewohner laufen, wie lange, und wie viel Strom verbrauchen sie dabei?","rueckmeldung":[{"option":1,"text":"Wer selbst gegen eine Regel verstößt, wirkt als Kritiker schnell unglaubwürdig, das macht den Gegenvorwurf so griffig. Ob dein Mitbewohner zu viel Strom verbraucht, hängt aber nicht davon ab, was du tust; entkräftet wird deine Kritik dadurch nicht."},{"option":2,"text":"Ein Kritiker, der selbst nicht konsequent ist, wirkt angreifbarer, und daher klingt „teilweise“ vernünftig. Wie stark das Argument ist, hängt aber an Logik und Belegen, nicht an der Konsequenz des Sprechers."},{"option":3,"text":"Dein Flurlicht darf durchaus zur Sprache kommen, und etwas Selbstprüfung schadet nie. Die Kritik braucht dafür aber keine Vorbedingung: Ob er zu viel Strom verbraucht, klärt sich unabhängig davon, was du selbst tust."}],"familie":"du-auch-erkennen","fertigkeit":"F2"},{"id":"qx-d1-017","clusterId":"D","werkstueckRef":"D.1.5","stufe":2,"question":"Was ist die beste Reaktion von A auf diesen Konter?","scenario":"In einer Diskussion sagt A: „Euer Land lässt Menschen in Haft schlecht behandeln, das muss sich ändern.“ B antwortet sofort: „Und was ist mit eurer Polizeigewalt? Darüber redet ihr natürlich nie!“ Der Vorwurf der Polizeigewalt gegen das Land von A trifft tatsächlich zu; zu den Haftbedingungen im eigenen Land sagt B aber nichts.","options":["A bestreitet die Polizeigewalt im eigenen Land, denn solange der Gegenvorwurf nicht widerlegt ist, kann die ursprüngliche Kritik nicht weiterverfolgt werden.","A erkennt die Polizeigewalt als ernstes, eigenes Thema an, bleibt aber bei den Haftbedingungen, weil der Gegenvorwurf die ursprüngliche Kritik nicht entkräftet.","A zieht die Kritik zurück, weil der Gegenvorwurf zeigt, dass beide Länder Fehler machen und die Kritik deshalb nicht mehr glaubwürdig ist.","A beginnt eine ausführliche Debatte über Polizeigewalt, weil beide Missstände gleich wichtig sind und deshalb zuerst gemeinsam geklärt werden müssen."],"correctIndex":1,"explanation":"Dass der Gegenvorwurf zutrifft, ändert nichts an der Gültigkeit der ursprünglichen Kritik: Er verdient eine eigene Diskussion, entkräftet den ersten Punkt aber nicht. Diese Ablenkung nennt man Whataboutism, eine Form des „Du auch“-Fehlschlusses: Er verschiebt das Gespräch von der Sachebene auf die Frage, ob der Sprecher moralisch konsistent ist. Das Ziel ist oft nicht, das eigene Handeln zu rechtfertigen, sondern den Kritiker zum Schweigen zu bringen und ein Patt zu erzeugen. Am besten erkennt man das andere Problem an, trennt es aber vom ersten und kehrt zur offenen Frage zurück.","coreRule":"⚡ Ein anderer Missstand ist ein anderes Thema – er entlastet den ersten nicht.","beleg":"Werkstück D.1.5 (Kontext & Tiefe: Whataboutism; Das Anti-Denkmuster: Skript 2)","status":"entwurf","kurz":"Der Gegenvorwurf stimmt, entkräftet die erste Kritik aber nicht: Ob es Polizeigewalt gibt, sagt nichts über die Haftbedingungen. Der Fehler liegt darin, auf die Konsistenz des Sprechers statt auf die Sache zu schauen. Darum: anerkennen, trennen, zurück zur Frage.","prueffrage":"Über welchen Missstand in welchem Land hat A gesprochen, und worüber spricht B in seiner Antwort?","rueckmeldung":[{"option":0,"text":"Den Gegenvorwurf zu bestreiten, wirkt wie Verteidigung, dabei trifft er zu. Und die Kritik an den Haftbedingungen bleibt gültig, ganz gleich, ob er sich widerlegen lässt oder nicht."},{"option":2,"text":"Dass beide Länder Fehler machen, stimmt vielleicht. Die Haftbedingungen werden dadurch aber nicht besser, und die Kritik daran wird nicht ungültig. Zurückzuziehen wäre genau das Schweigen, auf das der Konter oft zielt."},{"option":3,"text":"Polizeigewalt ist tatsächlich ein wichtiges Thema und verdient ein eigenes Gespräch. Gemeinsam und zuerst geklärt werden muss sie aber nicht: So verschwindet die ursprüngliche Frage, statt dass beide Punkte nacheinander ernst genommen werden."}],"familie":"du-auch-erkennen","fertigkeit":"F2"},{"id":"qx-d1-018","clusterId":"D","werkstueckRef":"D.1.5","stufe":3,"question":"Vier Personen reagieren auf Kritik oder auf Heuchelei. In welchem Satz wird der Heuchelei-Vorwurf berechtigt verwendet und nicht als Tu-quoque-Fehlschluss?","options":["„Die Wirtschaftszahlen von Politiker X können nicht stimmen, weil er Wasser predigt und Wein trinkt.“","„Dass Rauchen schädlich ist, kann nicht stimmen, denn die Ärztin, die uns das sagt, raucht ja selbst.“","„Meine Quellen sind genauso gut, denn die ‚Mainstream-Medien‘ haben schließlich auch schon gelogen.“","„Ich wähle Politiker X nicht, weil er Wasser predigt und Wein trinkt.“"],"correctIndex":3,"explanation":"Ein Heuchelei-Vorwurf ist berechtigt, wenn es um die Glaubwürdigkeit oder Eignung einer Person geht, etwa bei der Frage, ob man sie in ein Amt wählt. Zum Fehlschluss wird er, sobald er ein Tatsachenargument widerlegen soll. Ob Wirtschaftszahlen stimmen oder Rauchen schädlich ist, hängt an Daten und Belegen, nicht am Lebenswandel des Sprechers. Auch der Medien-Satz ist kein berechtigter Heuchelei-Vorwurf, sondern Whataboutism, eine Form des Tu quoque: Dass Medien Fehler machen, beweist nicht, dass andere Quellen stimmen. Ein Mörder, der „Morden ist falsch“ sagt, hat trotz seiner Heuchelei recht.","coreRule":"⚡ Heuchelei darf die Wahl einer Person beeinflussen, aber nie die Wahrheit ihrer Sachaussagen.","beleg":"Werkstück D.1.5 (Der Kipppunkt: legitim vs. Fehlschluss; Anwendung & Relevanz)","status":"entwurf","kurz":"Ob jemand für ein Amt glaubwürdig und geeignet ist, darf man am Verhalten messen; ob Zahlen oder Fakten stimmen, nicht. Der naheliegende Fehler ist, den Lebenswandel eines Sprechers gegen sein Argument zu wenden, obwohl Daten und Belege entscheiden.","prueffrage":"Was soll in jedem der vier Sätze am Ende entschieden oder bewiesen werden?","rueckmeldung":[{"option":0,"text":"Gegen Politiker X mag der Vorwurf berechtigt sein, wenn es um seine Glaubwürdigkeit geht. Hier soll er aber die Wirtschaftszahlen widerlegen, und ob Zahlen stimmen, zeigt sich an Daten und Belegen, nicht an seinem Lebenswandel."},{"option":1,"text":"Dass die Ärztin selbst raucht, mag widersprüchlich sein. Ob Rauchen schädlich ist, lässt sich aber nur an Studien und Daten prüfen, nicht am Verhalten der Sprecherin. Ihre Aussage bleibt davon unberührt."},{"option":2,"text":"Medien haben schon Fehler gemacht, das stimmt; der Satz ist aber kein Heuchelei-Vorwurf, sondern Whataboutism, eine Form des Tu quoque. Fehler der einen Seite sagen nichts darüber, ob die eigenen Quellen stimmen; auch die müssen sich prüfen lassen."}],"familie":"du-auch-erkennen","fertigkeit":"F2"},{"id":"qx-d1-019","clusterId":"D","werkstueckRef":"D.1.5","stufe":4,"question":"Was folgt für die Frage, ob Homöopathie wirkt, selbst dann, wenn dieser Vorwurf stimmt?","scenario":"Du sagst, Homöopathie habe keine plausible Wirkung. Dein Gegenüber antwortet: „Und die Todesfälle und Nebenwirkungen der Schulmedizin? Die Pharmaindustrie ist viel schlimmer!“","options":["Es folgt nichts, weil der Gegenvorwurf nichts über die Wirksamkeit der Homöopathie aussagt.","Es folgt, dass beide Verfahren gleichwertig sind, weil jedes Verfahren seine Schattenseiten hat.","Es folgt, dass deine Kritik zurückgenommen werden muss, weil die Schulmedizin selbst Fehler macht.","Es folgt, dass die Homöopathie ein Stück weit bestätigt ist, weil sie im Vergleich besser dasteht."],"correctIndex":0,"explanation":"Der Konter wechselt von der Sachfrage („Wirkt Homöopathie?“) zu einem Gegenvorwurf gegen die Schulmedizin. Selbst wenn der Vorwurf gegen „Big Pharma“ zutrifft, beweist er nicht, dass Homöopathie wirkt. Ob sie wirkt, hängt allein an ihrer eigenen Plausibilität und Evidenz.","coreRule":"⚡ Die Fehler der anderen Seite sind kein Beleg für die eigene.","beleg":"Werkstück D.1.5 (Anwendung & Relevanz: Pseudomedizin & Esoterik)","status":"entwurf","kurz":"Der Gegenvorwurf betrifft die Schulmedizin, nicht die Homöopathie. Selbst wenn er stimmt, bleibt die Frage offen, ob Homöopathie wirkt; das hängt allein an ihrer eigenen Plausibilität und Evidenz.","prueffrage":"Welche Untersuchung bräuchte man, um zu klären, ob Homöopathie wirkt?","rueckmeldung":[{"option":1,"text":"Dass jedes Verfahren Schattenseiten hat, kann stimmen. Gleichwertig sind zwei Verfahren damit aber nicht: Schattenseiten sagen nichts darüber, ob und wie gut etwas wirkt."},{"option":2,"text":"Deine Kritik galt der Wirkung der Homöopathie, nicht der Fehlerlosigkeit der Schulmedizin. Fehler dort können real sein, ändern aber nichts an dem, was du über die Homöopathie gesagt hast."},{"option":3,"text":"Wer weniger Schäden anrichtet, steht beim Schaden besser da. Ob etwas wirkt, ist damit nicht gezeigt: Das hängt an der eigenen Evidenz, nicht am Vergleich mit einem anderen Verfahren."}],"familie":"du-auch-erkennen","fertigkeit":"F2"},{"id":"qx-d1-020","clusterId":"D","werkstueckRef":"D.2.1","stufe":1,"question":"Was wäre der sinnvollste nächste Schritt, bevor du dich entscheidest?","scenario":"Bei einer Infoveranstaltung eines Tierheims erzählt eine Rednerin ohne eine einzige Zahl von „Rocky“, einem zitternden, abgemagerten Hund, der bei jeder Berührung zusammenzuckte. Ein kurzes Video zeigt, wie Rocky nach Wochen der Pflege wieder mit dem Schwanz wedelt. Eingeblendet wird: „Für nur 50 Cent am Tag kannst du die nächste Erfolgsgeschichte schreiben.“ Im Publikum werden Portemonnaies gezückt. Du überlegst, ob du spenden sollst.","options":["Du spendest sofort, denn die Geschichte zeigt, dass die Hilfe wirkt und dass das Tierheim gut arbeitet.","Du fragst nach belegbaren Angaben dazu, wie viel Geld tatsächlich bei den Tieren ankommt und was die Programme bewirken.","Du spendest nur dann, wenn dich die Geschichte nach einer Nacht Abstand immer noch emotional berührt.","Du fragst nach weiteren Einzelschicksalen wie Rocky, damit du dir ein vollständigeres Bild machen kannst."],"correctIndex":1,"explanation":"Die Geschichte weckt Mitleid, und das ist verständlich. Sie beweist aber nichts über die Effizienz der Organisation: Sie zeigt nur, dass ein Tier gelitten hat und dass einem Einzelfall geholfen wurde, nicht ob das Tierheim insgesamt wirksam arbeitet. Die Emotion ist nicht das Problem; zum Fehlschluss wird sie, wenn sie Beweise und Logik ersetzt. Die Frage nach Mittelverwendung und Wirkung trennt die Gefühlslage vom eigentlichen Argument. Abwarten allein prüft nichts: Nötig sind faktische Belege, die unabhängig vom Gefühl gelten, und eine Nacht Abstand liefert diese Belege nicht. Weitere Einzelschicksale liefern mehr vom Gleichen, also mehr Gefühl statt Belege.","coreRule":"⚡ Eine bewegende Geschichte zeigt, dass jemand leidet – nicht, dass die Hilfe wirkt. Frage nach den Belegen, die auch ohne dein Gefühl gelten.","beleg":"Werkstück D.2.1 (Einstiegsszene „Die Rede im Tierheim“; Kontext & Tiefe: Appell an das Mitleid)","status":"entwurf","kurz":"Rockys Geschichte weckt Mitleid, belegt aber nur einen Einzelfall, nicht die Wirksamkeit des Tierheims. Wer nach Mittelverwendung und Wirkung fragt, trennt das Gefühl vom eigentlichen Argument, statt es als Beweis zu nehmen.","prueffrage":"Was hast du bei der Veranstaltung über das Tierheim erfahren, abgesehen davon, wie es Rocky ergangen ist?","rueckmeldung":[{"option":0,"text":"Dass Rocky geholfen wurde, glaubst du gern, und es berührt zu Recht. Aus einem Einzelfall folgt aber nicht, dass das Tierheim insgesamt gut arbeitet oder dass dein Geld dort ankommt."},{"option":2,"text":"Eine Nacht Abstand dämpft den ersten Impuls, das ist ein Gewinn. Sie bringt aber keine neuen Informationen über Mittelverwendung und Wirkung, und ein anhaltendes Gefühl ersetzt auch am nächsten Tag keinen Beleg."},{"option":3,"text":"Mehr Einzelschicksale wirken wie gründlicheres Informieren, liefern aber nur mehr vom Gleichen: zusätzliche Rührung statt Angaben dazu, wie das Tierheim insgesamt arbeitet und was mit dem Geld geschieht."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2"},{"id":"qx-d1-021","clusterId":"D","werkstueckRef":"D.2.1","stufe":2,"question":"Woran erkennst du hier am ehesten einen manipulativen emotionalen Appell?","scenario":"Ein Werbespot zeigt nachts einen dunklen Hausflur, ein Geräusch, eine zitternde Familie, dazu düstere Musik – und dann das Angebot, zweimal hintereinander eingeblendet: „Mit der Alarmanlage XY schlafen Sie wieder ruhig.“","options":["Der Spot arbeitet mit Bildern und Musik statt mit Text, daher ist er ein Fehlschluss.","Die Lösung passt genau zur geweckten Emotion, und Prüfbares fehlt.","Der Spot löst Angst aus, daher ist die Bedrohung übertrieben dargestellt.","Der Spot wiederholt seine Botschaft mehrfach, daher ist er ein emotionaler Appell."],"correctIndex":1,"explanation":"Ein auffälliges Muster ist, dass erst eine Angst geweckt und im selben Moment die passende „Lösung“ angeboten wird. Bilder, Musik und Gefühle sind für sich kein Fehler: Ein Appell, der auf einer soliden faktischen Grundlage steht und Emotionen nutzt, um zum Handeln zu bewegen, ist legitim. Zum Trugschluss wird er erst, wenn die Emotion die einzige Grundlage ist und das Fehlen von Fakten verschleiert. Dass der Spot Angst auslöst, sagt nichts darüber, ob die Bedrohung übertrieben ist. Dass er seine Botschaft wiederholt, ist kein Kriterium für Manipulation. Entscheidend ist also, ob außer dem Gefühl etwas Überprüfbares geboten wird.","coreRule":"⚡ Achte darauf, wer dir Angst macht – und was er dir im selben Moment verkauft.","beleg":"Werkstück D.2.1 (Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Verdächtig wird der Spot, weil er erst Angst weckt und im selben Moment die passende Lösung anbietet, ohne dass etwas Prüfbares geboten wird. Emotion allein ist kein Fehler; sie wird erst zum Trugschluss, wenn sie die einzige Grundlage ist.","prueffrage":"Was bliebe von dem Spot übrig, wenn man Bilder und Musik weglässt und nur den eingeblendeten Satz liest?","rueckmeldung":[{"option":0,"text":"Bilder und Musik sind erst einmal nur Gestaltungsmittel, kein Fehler. Auch ein Spot ohne viel Text kann sachlich überzeugen, wenn er Prüfbares bietet. Entscheidend ist, was hinter den Bildern steht, nicht das Medium."},{"option":2,"text":"Dass Angst ausgelöst wird, stimmt, sagt aber nichts über die Größe der Bedrohung: Auch eine reale Gefahr macht Angst. Aufschlussreicher ist, ob der Spot außer dem Gefühl noch etwas Überprüfbares liefert."},{"option":3,"text":"Wiederholung allein macht einen Appell nicht manipulativ, denn auch sachliche Werbung wiederholt ihre Botschaft. Aussagekräftig ist, ob außer dem Gefühl etwas Prüfbares geboten wird."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2"},{"id":"qx-d1-022","clusterId":"D","werkstueckRef":"D.2.1","stufe":3,"question":"Wann würde dieser Appell tatsächlich zum Trugschluss?","scenario":"Eine Umweltorganisation zeigt Fotos verschmutzter Flüsse und nennt dazu gemessene Schadstoffwerte. Eine Freundin nennt das „Emotionsmache“ und meint, schon die Bilder machten den Appell unseriös.","options":["Sobald die Bilder Mitgefühl oder Empörung auslösen, weil dann das analytische Denken ausgeschaltet wird.","Sobald neben den Bildern auch Zahlen genannt werden, weil sich Gefühl und Zahl gegenseitig entwerten.","Sobald die Emotion die einzige Grundlage des Appells ist, weil sie dann das Fehlen von Fakten verschleiert.","Sobald die Organisation zusätzlich um Spenden bittet, weil ein Eigeninteresse jede Darstellung entwertet."],"correctIndex":2,"explanation":"Dass ein Argument Gefühle auslöst, macht es noch nicht fehlerhaft. Gefühle sind oft der Antrieb, sich überhaupt mit einem wichtigen Thema zu befassen. Ein Appell, der auf soliden Fakten steht und Emotionen nutzt, um zum Handeln zu bewegen, ist legitim. Zum Trugschluss wird er erst, wenn die Emotion die einzige Grundlage ist und das Fehlen von Fakten verschleiert. Hier tragen die gemessenen Schadstoffwerte das Argument; die Bilder machen es nur eindringlicher. Der Test: Würde die Behauptung auch dann noch gelten, wenn du die Gefühle beiseitelegst und nur die Belege betrachtest? Das Eigeninteresse einer Organisation oder die bloße Nennung von Zahlen widerlegt weder die Messwerte noch macht sie das Argument schwächer.","coreRule":"⚡ Gefühl darf der Antrieb sein – das Argument muss auch ohne das Gefühl tragen.","beleg":"Werkstück D.2.1 (Der Kipppunkt; Kontext & Tiefe)","status":"entwurf","kurz":"Der Appell kippt erst, wenn Emotion das Einzige ist, was ihn trägt, und Fakten fehlen. Gefühle allein entwerten ihn nicht: Hier stützen Messwerte die Aussage, die Bilder machen sie nur eindringlicher.","prueffrage":"Woher stammen die genannten Schadstoffwerte, und wer könnte sie nachmessen?","rueckmeldung":[{"option":0,"text":"Bilder können Mitgefühl und Empörung wecken, das stimmt. Daraus folgt aber nicht, dass das Denken abgeschaltet wird: Gefühle bringen Menschen oft erst dazu, sich mit einem Thema zu befassen. Entscheidend ist, ob Belege dahinterstehen."},{"option":1,"text":"Zahlen neben Bildern schwächen sich nicht gegenseitig. Gerade die Messwerte tragen hier das Argument, und die Bilder machen es anschaulicher. Fehlten die Zahlen, wäre der Appell angreifbarer, nicht umgekehrt."},{"option":3,"text":"Eine Spendenbitte zeigt ein Eigeninteresse, das du bei der Einordnung im Blick behalten kannst. Die Schadstoffwerte lassen sich aber unabhängig vom Absender nachprüfen, und ein Eigeninteresse macht sie nicht falsch."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2"},{"id":"qx-d1-023","clusterId":"D","werkstueckRef":"D.2.2","stufe":1,"question":"Ein Kollege wendet ein: „Das ist doch völlig in Ordnung – gelogen hat der Manager nicht, es sind ja wirklich 50 Positionen.“ Was ist an dieser Verteidigung übersehen?","scenario":"Ein Manager kündigt eine „Freisetzung von Personalressourcen im Umfang von 50 Positionen“ an. Tatsächlich verlieren 50 Menschen ihren Job. In der Belegschaft klingt die Ankündigung deutlich weniger bedrohlich, als wenn der Manager gesagt hätte, 50 Mitarbeiter würden gekündigt.","options":["Dass eine Aussage ohne falsche Tatsache trotzdem lenken kann: Dieselbe Realität in milderen Worten verändert den Eindruck, ohne eine Lüge zu sein.","Dass die Aussage doch eine Lüge ist, weil das Wort „entlassen“ nicht vorkommt und deshalb etwas Falsches behauptet wird.","Dass die Wortwahl keine Rolle spielt, weil beide Formulierungen dieselbe Zahl nennen und der Eindruck bei allen gleich ausfällt.","Dass der Manager härtere Wörter hätte wählen müssen, weil nur eine möglichst scharfe Formulierung die Belegschaft angemessen informiert."],"correctIndex":0,"explanation":"Der Kollege prüft nur, ob die Zahl stimmt. Das tut sie: Die Ankündigung nennt 50 Positionen, und tatsächlich verlieren 50 Menschen ihren Job. Die milde Formulierung lügt also nicht, färbt die Realität aber durch die Wahl der Worte um. Gelenkt wird nicht über die Zahl, sondern über die Wortwahl. „Freisetzung von Personalressourcen“ ersetzt eine harte Aussage durch milde, vage Begriffe. Das ist ein Euphemismus, ein Weichzeichner. Die Verteidigung vermischt zwei Fragen: „Ist es wahr?“ und „Wie wird mein Urteil gelenkt?“. Ein Test: Ersetze die Begriffe durch die neutralsten, sachlichsten Wörter, die du findest. Übrig bleibt: 50 Menschen verlieren ihre Stelle. Dass dieser Satz anders wirkt als die Ankündigung, zeigt, wie viel die Wortwahl bewirkt hat.","coreRule":"⚡ Ein Weichzeichner-Wort ändert den Eindruck, nicht die Tatsache.","beleg":"Werkstück D.2.2 (Einstiegsszene „Die Entscheidung des Managers“; „Kontext & Tiefe“, Punkt „Euphemismen (Die Weichzeichner)“; keine Fußnoten)","status":"entwurf","kurz":"Dass die Zahl stimmt, heißt nicht, dass die Wortwahl nichts bewirkt. „Freisetzung von Personalressourcen“ lügt nicht, färbt aber um, und gelenkt wird über die Worte, nicht über die Zahl. Wahr zu sein und neutral zu wirken sind zwei verschiedene Fragen.","prueffrage":"Wie würde dieselbe Ankündigung klingen, wenn du nur die nüchternsten Wörter benutzt, die dir einfallen?","rueckmeldung":[{"option":1,"text":"Dass ein Wort fehlt, macht eine Aussage noch nicht falsch: Es verlieren tatsächlich 50 Menschen ihre Stelle, und genau das nennt die Ankündigung nur in milden Worten. Beschönigend ist sie, aber keine Lüge."},{"option":2,"text":"Beide Formulierungen nennen zwar dieselbe Zahl, wirken aber nicht gleich: In der Belegschaft klingt die erste deutlich weniger bedrohlich. Gleicher Inhalt bedeutet also nicht gleichen Eindruck, und genau darin liegt die Lenkung."},{"option":3,"text":"Klar informiert die milde Formulierung die Belegschaft tatsächlich nicht. Eine möglichst scharfe Formulierung wäre aber ebenfalls gefärbt, nur in die andere Richtung. Gesucht sind die neutralsten, sachlichsten Wörter."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2"},{"id":"qx-d1-024","clusterId":"D","werkstueckRef":"D.2.2","stufe":2,"question":"Was folgt aus dieser Konstellation für die Beurteilung der drei Berichte?","scenario":"Drei Nachrichtenportale berichten über denselben Mann, der mit Waffengewalt gegen eine Regierung kämpft. Portal A nennt ihn „Freiheitskämpfer“, Portal B „Terrorist“, Portal C „Aufständischer“. Alle drei melden dieselben Fakten: Ort, Zeitpunkt, Anzahl der Angriffe.","options":["Genau eines der Wörter ist sachlich zutreffend, die anderen beiden sind leicht erkennbare Beschönigungen oder Abwertungen.","Mindestens zwei der Portale lügen, denn derselbe Mann kann nicht zugleich Held, Schurke und Akteur sein.","Die Wortwahl ist belanglos, solange die berichteten Tatsachen übereinstimmen und die Definition passt.","Alle drei Wörter passen auf dieselbe Person, aber jedes legt schon ein Urteil nahe."],"correctIndex":3,"explanation":"Wörter haben eine Wörterbuch-Bedeutung (Denotation) und tragen zusätzlich Assoziationen (Konnotation). Alle drei Begriffe können auf denselben Mann passen, weil die Fakten übereinstimmen. Sie unterscheiden sich aber darin, ob sie ihn eher als Helden, als Schurken oder als neutralen Akteur erscheinen lassen. Das ist keine Lüge, aber eine Lenkung der Wahrnehmung: Das Urteil steckt schon im Wort. Wer die Berichte prüft, ersetzt die geladenen Wörter probeweise durch möglichst neutrale Beschreibungen („bewaffneter Kämpfer gegen die Regierung“) und fragt, was dann als nackte Tatsachenaussage übrig bleibt. Die Wortwahl für belanglos zu halten, übersieht diese Wirkung. Und nach dem einen „richtigen“ Wort zu suchen, verkennt, dass mehrere Bezeichnungen dieselbe Person treffen können.","coreRule":"⚡ Wörter beschreiben nicht nur, sie urteilen schon mit.","beleg":"Werkstück D.2.2 (Kontext & Tiefe: Geladene Sprache – denotativ/konnotativ; Das Anti-Denkmuster)","status":"entwurf","kurz":"Alle drei Wörter können auf denselben Mann passen, denn die Fakten stimmen überein. Sie lassen ihn aber unterschiedlich erscheinen. Das ist keine Lüge, doch das Urteil steckt schon im Wort.","prueffrage":"Was bleibt von jedem Bericht übrig, wenn du die Bezeichnung für den Mann durch eine bloße Beschreibung ersetzt?","rueckmeldung":[{"option":0,"text":"„Aufständischer“ wirkt tatsächlich neutraler als die anderen beiden. Doch auch „Freiheitskämpfer“ und „Terrorist“ können auf denselben Mann passen; sie sind nicht falsch, sondern werten. Die Suche nach dem einen richtigen Wort führt in die Irre."},{"option":1,"text":"Die Wörter legen tatsächlich gegensätzliche Urteile nahe. Gelogen wird aber nicht: Alle drei melden dieselben Fakten und können denselben Mann treffen. Gegensätzlich sind die Wertungen, nicht die berichteten Tatsachen."},{"option":2,"text":"Übereinstimmende Fakten sind eine gute Basis, und die Wörter passen auf den Mann. Trotzdem wirkt die Wortwahl: Ein geladener Begriff lenkt die Wahrnehmung, auch wenn kein Faktum verändert wird."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2"},{"id":"qx-d1-025","clusterId":"D","werkstueckRef":"D.2.2","stufe":3,"question":"Was ist an dem Einwand des Kollegen fehlerhaft, und woran erkennst du, wann ein Euphemismus tatsächlich manipulativ wird?","scenario":"In einer Pressemitteilung steht: „Im Rahmen einer Neuausrichtung setzen wir 50 Personalressourcen frei.“ Gleichzeitig sagt jemand aus der Belegschaft einer Kollegin, die einen Angehörigen verloren hat: „Er ist von uns gegangen.“ Ein Kollege meint: „Beides ist derselbe Trick, denn beides schwächt ein hartes Wort ab. Wer so redet, manipuliert.“","options":["Der Einwand stimmt, weil jeder Euphemismus die Wirklichkeit verschleiert; manipulativ ist er also schon beim ersten beschönigenden Wort.","Der Einwand verwechselt Beschönigung mit Täuschung; manipulativ wird ein Euphemismus erst, wenn er eine falsche Tatsache behauptet.","Der Einwand stimmt, solange der Sprecher ein Eigeninteresse hat; ob die Absicht taktvoll ist, spielt für die Einordnung keine Rolle.","Der Einwand setzt Ungleiches gleich; Taktgefühl ist unproblematisch, manipulativ wird Wortwahl erst, wenn sie die Realität verzerrt."],"correctIndex":3,"explanation":"Ein weicheres Wort ist für sich genommen noch keine Manipulation. „Er ist von uns gegangen“ statt „Er ist tot“ drückt Mitgefühl aus, und alle Beteiligten wissen, was gemeint ist. Die Pressemitteilung dagegen kleidet den Verlust von 50 Arbeitsplätzen in Begriffe wie „Neuausrichtung“ und „Personalressourcen“, sodass die Betroffenen und ihr Schicksal kaum noch erkennbar sind. Das kippt, wenn Sprache systematisch dazu dient, die Realität so zu verzerren, dass eine nüchterne Bewertung kaum noch möglich ist. Die Pressemitteilung muss dafür nicht lügen: Sie beschreibt dieselbe Realität wie die harte Fassung, färbt sie aber um, sodass die eine Fassung harmlos wirkt und die andere brutal. Ein Prüfstein ist, die geladenen Wörter durch die neutralsten zu ersetzen und zu fragen, was als nackte Aussage übrig bleibt. Beim Trauerfall bleibt dieselbe Aussage und niemand wird getäuscht; bei der Pressemitteilung wird erst dadurch sichtbar, was geschieht.","coreRule":"⚡ Rücksicht in der Wortwahl ist Höflichkeit – erst die systematische Verzerrung macht daraus Manipulation.","beleg":"Werkstück D.2.2 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Zwei weiche Formulierungen sind nicht dasselbe: „von uns gegangen“ ist taktvoll, und alle wissen, was gemeint ist. Manipulativ wird Wortwahl erst, wenn sie die Realität so verzerrt, dass eine nüchterne Bewertung kaum noch möglich ist.","prueffrage":"Wüsste jemand, der nur einen der beiden Sätze hört, jeweils genau, was den Betroffenen geschehen ist?","rueckmeldung":[{"option":0,"text":"Dass Euphemismen die Wirklichkeit abmildern, stimmt. Daraus folgt aber keine Manipulation: Beim Trauerfall drückt das weichere Wort Mitgefühl aus, und niemand wird über das Geschehene getäuscht."},{"option":1,"text":"Beschönigung und Täuschung auseinanderzuhalten, ist ein guter Ansatz. Zu eng ist nur die Bedingung: Eine Pressemitteilung muss nichts Falsches behaupten, um zu manipulieren. Es genügt, dieselbe Realität so umzufärben, dass sie harmlos wirkt."},{"option":2,"text":"Ein Eigeninteresse kann ein Anlass sein, genauer hinzusehen. Es macht eine Wortwahl für sich aber nicht manipulativ, und die Absicht spielt durchaus eine Rolle: Wer mit „von uns gegangen“ Anteilnahme zeigt, verzerrt nichts."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2"},{"id":"qx-d1-026","clusterId":"D","werkstueckRef":"D.2.2","stufe":4,"question":"Welche Prüfung hilft am besten, die Wirkung dieser Wortwahl zu durchschauen?","scenario":"Eine Broschüre schreibt: „Man leitet keine Gifte aus, man unterstützt den Körper bei seiner natürlichen Reinigung – ganzheitlich, sanft und harmonisierend.“","options":["Zählen, ob mehr positiv als negativ geladene Wörter vorkommen; ein Übergewicht positiver Wörter beweist die Täuschung eindeutig.","Den Satz ins Gegenteil verkehren und prüfen, ob er dann ebenso überzeugend klingt wie vorher.","Geladene Wörter und Beschönigungen probeweise durch neutrale, sachliche Begriffe ersetzen und fragen, welche Tatsachenbehauptung übrig bleibt.","Herausfinden, wer die Broschüre verfasst hat, und die Aussagen vor allem nach den möglichen Motiven des Verfassers bewerten."],"correctIndex":2,"explanation":"Wörter wie „sanft“, „ganzheitlich“ oder „harmonisierend“ transportieren ein Urteil, ohne etwas zu belegen. Ersetzt du sie probeweise durch neutrale Begriffe, siehst du, was tatsächlich behauptet wird: dass der Körper Stoffe ausscheidet und dass die beworbene Methode dabei hilft. Genau diese Behauptung lässt sich dann prüfen: Welcher Stoff? Wie nachgewiesen? Mit welcher Wirkung? Positive Wörter zu zählen beweist nichts, denn auch ein ehrlicher Text darf freundlich formuliert sein. Den Satz ins Gegenteil zu verkehren zeigt höchstens, dass Wortwahl wirkt, nicht, ob die Aussage stimmt. Und die Absichten der Verfasser zu bewerten ersetzt keine Prüfung der Aussage selbst: Auch ein Mensch mit Eigeninteresse kann recht haben, und ein Mensch ohne kann sich irren.","coreRule":"⚡ Streich die Gefühlswörter weg und schau, was als Behauptung übrig bleibt.","beleg":"Werkstück D.2.2 (Anwendung & Relevanz: In der Pseudomedizin; Das Anti-Denkmuster)","status":"entwurf","kurz":"Ersetzt du die geladenen Wörter probeweise durch neutrale, bleibt eine prüfbare Tatsachenbehauptung übrig: Der Körper scheidet Stoffe aus, und die Methode hilft dabei. Die Wörter selbst belegen nichts, sie transportieren nur ein Urteil.","prueffrage":"Welcher Stoff soll den Körper verlassen, und woran würdest du merken, dass die Methode dabei hilft?","rueckmeldung":[{"option":0,"text":"Viele positive Wörter können auf werbende Sprache hinweisen. Beweisen tut das Zählen aber nichts: Auch ein ehrlicher Text darf freundlich klingen, und über die Tatsachenbehauptung selbst sagt die Wortzahl nichts."},{"option":1,"text":"Der Umkehrtest zeigt höchstens, dass Wortwahl wirkt: Das Gegenteil klingt vermutlich weniger überzeugend. Ob die Aussage stimmt, ergibt sich daraus nicht, denn das hängt an den Tatsachen, nicht am Klang."},{"option":3,"text":"Wer etwas verkauft, hat womöglich ein Eigeninteresse, und das kann Anlass zu genauerem Hinsehen sein. Es ersetzt aber nicht die Prüfung der Aussage: Auch wer verdient, kann recht haben, und wer nichts davon hat, kann sich irren."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2"},{"id":"qx-d1-027","clusterId":"D","werkstueckRef":"D.2.3","stufe":1,"question":"Eine Leserin sagt: „Eine der beiden Zeitungen muss lügen, denn eine Steuererhöhung kann nicht zugleich Investition und Enteignung sein.“ Was ist an diesem Schluss fehlerhaft?","scenario":"Dieselbe Steuererhöhung wird in einer Zeitung als „Investition in die Gemeinschaft“, in einer anderen als „Enteignung durch den Staat“ beschrieben. Beide Zeitungen nennen dieselben Zahlen.","options":["Er übersieht, dass beide Begriffe denselben Sachverhalt in einen unterschiedlichen Deutungsrahmen setzen können, ohne dass eine Zeitung eine falsche Tatsache behauptet.","Er übersieht, dass beide Begriffe im selben Deutungsrahmen austauschbare Synonyme sind, weil bei gleichen Zahlen jede Wortwahl dieselbe Wirkung hat.","Er übersieht, dass der Begriff „Enteignung“ die sachlich korrekte Bezeichnung ist und „Investition“ den Deutungsrahmen erst künstlich setzt.","Er übersieht, dass Zeitungen grundsätzlich keinen eigenen Deutungsrahmen wählen, sondern amtliche Begriffe übernehmen und deshalb nicht widersprüchlich berichten."],"correctIndex":0,"explanation":"Hier konkurrieren zwei Deutungsrahmen: der Gemeinschafts-Frame („Bürgerpflicht“, „Investition in die soziale Gemeinschaft“) und der Freiheits-Frame („Last“, „Enteignung durch den Staat“, Einschränkung der individuellen Freiheit). Je nachdem, welcher Frame dominiert, werden Steuererhöhungen als Investition oder als Diebstahl wahrgenommen. Der Unterschied liegt in Wortwahl und Blickwinkel, nicht in den Zahlen: Beide Zeitungen nennen dieselben Zahlen. Wer „Lüge“ ruft, verwechselt Rahmung mit Falschbehauptung. Beide Begriffe gehören zu je einem Deutungsrahmen. Besser ist die Frage: Welche anderen Frames gibt es, welche Aspekte hebt jeder hervor, welche lässt er außen vor, und zu welchen Lösungen würden wir kommen?","coreRule":"⚡ Wer den Rahmen setzt, entscheidet mit, was dieselben Zahlen bedeuten.","quote":"Wer den Frame kontrolliert, kontrolliert die Debatte.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück D.2.3 (Kontext & Tiefe: Beispiel Steuern)","status":"entwurf","kurz":"Zwei Zeitungen können dieselben Zahlen nennen und die Sache dennoch verschieden rahmen: als Gemeinschaftsinvestition oder als staatlichen Zugriff. Der Denkfehler liegt darin, Rahmung mit Falschbehauptung zu verwechseln und deshalb „Lüge“ zu rufen.","prueffrage":"Was genau behaupten die beiden Zeitungen über die Steuererhöhung, wenn du Zahlen und Wertungen getrennt betrachtest?","rueckmeldung":[{"option":1,"text":"Dass beide Zeitungen dieselben Zahlen nennen, stimmt. Die Wortwahl wirkt aber gerade nicht gleich: „Investition“ und „Enteignung“ lenken die Wahrnehmung in entgegengesetzte Richtungen, sie sind keine austauschbaren Synonyme."},{"option":2,"text":"„Enteignung“ klingt nach einem festen Rechtsbegriff und damit nach Sachbeschreibung. Für eine Steuererhöhung ist es aber eine Wertung aus einem Deutungsrahmen, der die Freiheit betont, so wie „Investition“ eine aus dem Gemeinschaftsrahmen ist."},{"option":3,"text":"Die Annahme, Zeitungen übernähmen einfach amtliche Begriffe, würde den Widerspruch scheinbar auflösen. Gerade „Investition“ und „Enteignung“ zeigen aber, dass Redaktionen Wortwahl und Blickwinkel selbst bestimmen."}],"familie":"rahmen-wechseln","fertigkeit":"F2"},{"id":"qx-d1-028","clusterId":"D","werkstueckRef":"D.2.3","stufe":2,"question":"Welche Erwartung ist am besten begründet, wenn die Klinik beide Entwürfe an Laien und an Ärzten testet?","scenario":"Eine Klinik will Patienten mit Lungenkrebs über zwei Behandlungswege aufklären: Operation oder Bestrahlung. Beide Entwürfe der Aufklärungsbroschüre geben dieselben Ergebnisse der Operation an. Entwurf 1 schreibt: „Die Ein-Monats-Überlebensrate liegt bei 90 Prozent.“ Entwurf 2 schreibt: „Im ersten Monat beträgt die Sterblichkeitsrate 10 Prozent.“ Ein Klinikleiter ist überzeugt: „Ärzte und Fachleute sind gegen solche Formulierungstricks gefeit. Nur medizinische Laien lassen sich davon beeinflussen.“","options":["Dass die Formulierung auch bei Ärzten die Entscheidung verschiebt, ist plausibel: Die Information ist gleich, aber der Rahmen aus Gewinn oder Verlust wirkt häufig unabhängig von Fachwissen.","Dass sich nur Laien beeinflussen lassen, ist plausibel: Fachwissen schützt weitgehend vor Unterschieden in der Darstellung derselben Zahlen.","Dass die Formulierung bei niemandem eine Rolle spielt, ist plausibel: Wer dieselben Zahlen liest, entscheidet in der Regel gleich, auch wenn sie anders dargestellt werden.","Dass die Sterblichkeitsformulierung zu mehr Operationen führt, ist plausibel: Eine Verlustdarstellung lässt eine Entscheidung für den Eingriff meist klarer erscheinen."],"correctIndex":0,"explanation":"Der Klinikleiter behauptet etwas, das sich prüfen lässt: Schützt Fachwissen vor dem Rahmen? Genau das wurde 1982 untersucht (McNeil u. a., New England Journal of Medicine): 238 Patienten mit anderen chronischen Erkrankungen, 491 Studierende und 424 Ärzte sollten sich vorstellen, an Lungenkrebs erkrankt zu sein, und zwischen Operation und Bestrahlung wählen. In allen drei Gruppen war die Operation beliebter, wenn die Ergebnisse als Überlebenswahrscheinlichkeit statt als Sterblichkeit angegeben waren. Nach der Darstellung bei Kahneman (2012) wählten 84 Prozent der Ärzte die Operation, wenn von einer Ein-Monats-Überlebensrate von 90 Prozent die Rede war. Hieß es dagegen, im ersten Monat betrage die Sterblichkeitsrate 10 Prozent, zogen 50 Prozent die Bestrahlung vor. Gleiche Information führt also je nach Rahmen zu unterschiedlichen Entscheidungen, und Fachwissen schützt nicht davor. Vorsicht ist auch bei der Richtung geboten: Die Sterblichkeitsformulierung macht den Eingriff weniger attraktiv, nicht attraktiver.","coreRule":"⚡ Dieselbe Zahl als Gewinn oder als Verlust formuliert lenkt auch Fachleute: Wer eine Aussage prüft, sollte sie in beiden Rahmen lesen.","beleg":"Werkstück D.2.3 (Einstiegsszene); Fn. gl-d-mcneil (McNeil u. a. 1982, NEJM 306(21), S. 1259–1262; Kahneman 2012, Kap. 34)","status":"entwurf","kurz":"In einer bekannten Studie wählten auch Ärzte bei „90 Prozent überleben“ deutlich häufiger die Operation als bei „10 Prozent sterben“. Wer meint, Fachwissen schütze vor dem Rahmen, unterschätzt, wie stark Gewinn- oder Verlustdarstellung auch Fachleute lenkt.","prueffrage":"Worin unterscheiden sich die beiden Sätze, wenn die Zahlen dieselben sind, und was davon müsste ein Arzt anders lesen als ein Laie?","rueckmeldung":[{"option":1,"text":"Dass Laien beeinflusst werden, stimmt, aber der Schluss „nur Laien“ hält der Prüfung nicht stand. In der bekannten Studie dazu verschob der Rahmen auch die Wahl der Ärzte deutlich, Fachwissen schützte sie nicht."},{"option":2,"text":"Beide Entwürfe enthalten dieselbe Information, deshalb liegt gleiches Wählen nahe. In einer bekannten Studie zog aber bei der Sterblichkeitsangabe die Hälfte der Ärzte die Bestrahlung vor, bei der Überlebensangabe nur etwa jeder Sechste."},{"option":3,"text":"Dass die Formulierung wirkt, stimmt, nur die Richtung ist verdreht: Eine Verlustdarstellung lässt den Eingriff weniger attraktiv erscheinen. In einer bekannten Studie wurde die Operation bei der Überlebensangabe häufiger gewählt."}],"familie":"rahmen-wechseln","fertigkeit":"F2"},{"id":"qx-d1-029","clusterId":"D","werkstueckRef":"D.2.3","stufe":3,"question":"Wie beurteilst du seine Aussage am besten?","scenario":"Ein Bekannter sagt: „Menschen denken in Frames, nicht in Fakten. Wer einmal in einem Rahmen steckt, den kannst du mit einer Richtigstellung nicht erreichen – das bringt nie etwas.“ Du hast den Verdacht, dass er die These übertreibt.","options":["Als zugespitzt: Rahmen lenken die Wahrnehmung stark, doch Richtigstellungen wirken meist, und nur selten verpuffen sie.","Als zutreffend: Fakten ohne passenden Rahmen werden stets übergangen, und Richtigstellungen bleiben dadurch wirkungslos.","Als falsch: Rahmen spielen nur in der Werbung eine Rolle, und das politische Denken berühren sie überhaupt nicht.","Als zutreffend: Richtigstellungen kehren sich regelmäßig ins Gegenteil, und deshalb festigen sie den Irrtum immer."],"correctIndex":0,"explanation":"Die Aussage macht aus einer Tendenz ein Gesetz. Dass wir Informationen durch Deutungsrahmen ordnen und passende Fakten leichter aufnehmen als unpassende, ist plausibel; daraus folgt aber nicht, dass Fakten nie ankommen. Richtigstellungen verringern eine Fehlvorstellung meist, wenn auch oft nicht vollständig und nicht auf Dauer; dass sie ganz verpuffen oder sich ins Gegenteil verkehren, ist die Ausnahme. Wer die Aussage prüft, fragt daher nicht „Gibt es Rahmeneffekte?“, sondern „Wie stark und wie oft?“. Absolute Wörter wie „nie“ oder „immer“ sind dabei ein Warnsignal.","coreRule":"⚡ Rahmen lenken die Wahrnehmung, aber Fakten verlieren nicht automatisch dagegen: Wer „nie“ sagt, überzieht eine Tendenz zum Gesetz.","beleg":"Werkstück D.2.3 (Kontext & Tiefe: Lakoffs These und Einschränkung; Der Kipppunkt)","status":"entwurf","kurz":"Rahmen färben die Wahrnehmung, daraus folgt aber kein Gesetz: Richtigstellungen verringern Fehlvorstellungen meist, wenn auch oft nicht vollständig, und nur selten verpuffen sie. Der Fehler liegt darin, aus einer Tendenz ein „nie“ zu machen.","prueffrage":"Kennst du einen Fall, in dem jemand nach einer Richtigstellung seine Meinung tatsächlich geändert hat?","rueckmeldung":[{"option":1,"text":"Dass passende Fakten leichter ankommen als unpassende, ist plausibel. Doch „stets übergangen“ und „wirkungslos“ sind genauso absolut wie die ursprüngliche Aussage: Aus einer Tendenz wird wieder ein Gesetz, obwohl Richtigstellungen meist wirken."},{"option":2,"text":"Hier kippt die Übertreibung in die Gegenrichtung. Wir ordnen Informationen ganz allgemein durch Deutungsrahmen, nicht nur in der Werbung, und „überhaupt nicht“ ist wieder ein absolutes Wort, das Misstrauen wecken sollte."},{"option":3,"text":"Eine Richtigstellung, die das Gegenteil bewirkt, kommt vor, ist aber die Ausnahme. „Regelmäßig“ und „immer“ machen daraus eine Regel und verschärfen den Fehler des Bekannten noch: Aus „bringt nichts“ wird „schadet immer“."}],"familie":"rahmen-wechseln","fertigkeit":"F2"},{"id":"qx-d1-030","clusterId":"D","werkstueckRef":"D.2.3","stufe":4,"question":"Wie gehst du am klügsten mit dieser Rahmung um?","scenario":"In einer Debatte über Drogenpolitik wird das Thema durchgehend als „Krieg gegen Drogen“ geführt. Die Schlussfolgerung scheint schon in der Wortwahl mitzulaufen: Wer von Krieg spricht, denkt an Gegner, Härte und Sieg. Du willst den Rahmen nicht unbemerkt übernehmen.","options":["Den Rahmen akzeptieren und mit besseren Zahlen widerlegen, denn nur so lässt sich in der Debatte überzeugend argumentieren.","Auf jede Rahmung verzichten und nur Fakten nennen, denn Rahmungen sind grundsätzlich manipulativ und deshalb zu vermeiden.","Den Rahmen benennen und alternative Rahmen durchspielen, denn so zeigt sich, was er ausblendet.","Den Rahmen als bloße Metapher vorführen, denn so erkennt das Publikum sofort, dass er nichts taugt."],"correctIndex":2,"explanation":"Ein Rahmen bestimmt, welche Aspekte eines Themas sichtbar werden und welche Lösungen naheliegen. Wer seinen Rahmen durchsetzt, hat oft schon gewonnen, bevor die erste Zahl genannt wird; wer ihn unbemerkt übernimmt, denkt innerhalb der Vorgaben anderer. Beim Rahmen „Krieg“ geht es dann um Gegner und Siege, nicht um Ursachen und Behandlung. Besser ist es, den Rahmen sichtbar zu machen und Alternativen zu prüfen: Was ändert sich, wenn das Problem als Gesundheitsproblem oder als Bildungsaufgabe betrachtet wird? Zu welchen anderen Lösungen käme man dann? Rahmungen sind dabei nicht per se manipulativ, denn ohne sie können wir die Welt gar nicht ordnen. Zum Problem werden sie, wenn wir den Rahmen nicht bemerken, in dem wir denken. Eine bloße Gegenzahl innerhalb des fremden Rahmens ändert daran nichts, und der pauschale Verzicht auf jede Rahmung ist weder möglich noch nötig. Auch den Rahmen nur als „Metapher“ abzutun, ersetzt die Prüfung nicht: Es bleibt offen, was er sichtbar macht und was er verdeckt.","coreRule":"⚡ Frag nicht nur, ob die Fakten stimmen, sondern in welchem Rahmen sie dir gezeigt werden.","beleg":"Werkstück D.2.3 (Das Anti-Denkmuster; Das Adaptive Talent)","status":"entwurf","quote":"Welche anderen, alternativen Frames gibt es?","quoteLabel":"Prüffrage","kurz":"Ein Rahmen legt fest, was sichtbar wird und welche Lösungen naheliegen. Wer ihn benennt und Alternativen wie „Gesundheitsproblem“ durchspielt, sieht, was „Krieg“ ausblendet. Gegenzahlen innerhalb des Rahmens ändern daran wenig.","prueffrage":"Welche Maßnahmen gegen Drogenprobleme fallen dir ein, und welche davon passen zum Wort „Krieg“?","rueckmeldung":[{"option":0,"text":"Belege sind wichtig, und Zahlen können Behauptungen entkräften. Wer sie aber im Rahmen „Krieg“ vorbringt, streitet weiter über Gegner und Siege und lässt unbemerkt stehen, dass die Frage damit schon eingeengt ist."},{"option":1,"text":"Dass Rahmungen manipulativ wirken können, stimmt, vor allem wenn man sie nicht bemerkt. „Grundsätzlich“ ist aber zu viel: Ohne Rahmen lässt sich die Welt nicht ordnen, und auch eine reine Faktenauswahl setzt bereits einen Blickwinkel."},{"option":3,"text":"Den Begriff als Metapher zu erkennen, ist ein Anfang. Dass er „nichts taugt“, folgt daraus aber nicht: Entscheidend ist, was er sichtbar macht und was er verdeckt, und das zeigt sich erst im Vergleich mit anderen Rahmen."}],"familie":"rahmen-wechseln","fertigkeit":"F2"},{"id":"qx-d1-031","clusterId":"D","werkstueckRef":"D.2.4","stufe":1,"question":"Was ist an diesem Argument der Kernfehler?","scenario":"Dein Nachbar warnt: „Erst Tempo 30 vor der Schule, dann in der ganzen Straße, dann ein Autoverbot in der Innenstadt – am Ende gehen wir alle zu Fuß!“ Belege für die einzelnen Schritte nennt er nicht.","options":["Er stellt dich vor nur zwei Möglichkeiten, als gäbe es keine dritte Wahl.","Er greift die Verkehrsplanerinnen und -planer persönlich an, statt auf die Sache einzugehen.","Er verwirft jede Warnung vor Folgen, weil Vorhersagen immer Spekulation sind.","Er stellt die Folgen als zwangsläufig dar, ohne sie zu belegen."],"correctIndex":3,"explanation":"Das ist ein Dammbruch-Fehlschluss (Slippery Slope): Eine kleine erste Maßnahme soll unweigerlich in einer Katastrophe enden. Der Fehler liegt in der behaupteten Zwangsläufigkeit. Es wird so getan, als gäbe es zwischen Tempo 30 vor der Schule und dem Autoverbot keine Haltepunkte, etwa Gesetze, Gerichte, öffentliche Proteste oder den gesunden Menschenverstand. Eine Warnung vor einer wahrscheinlichen, belegten Folge wäre dagegen kein Fehlschluss. Hier ist die Kette nur behauptet, kein einziger Übergang ist belegt. Ein persönlicher Angriff liegt nicht vor, und ein Entweder-oder wird nicht aufgemacht. Eine Warnung vor Folgen ist nicht per se ein Fehlschluss: Entscheidend ist, ob Wahrscheinlichkeit und Gewicht der befürchteten Folge begründet sind (vgl. Hahn/Oaksford 2006).","coreRule":"⚡ Prüfe jeden Pfeil der Kette einzeln, nicht nur das Schreckensbild am Ende.","beleg":"Werkstück D.2.4 (Kernidee; Kontext & Tiefe; Fußnote gl-d-hahn: Hahn/Oaksford 2006)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Der Nachbar behauptet eine Kette, in der jeder Schritt unweigerlich den nächsten auslöst, und belegt keinen einzigen Übergang. Dabei übersieht er mögliche Haltepunkte wie Gesetze, Gerichte oder Proteste.","prueffrage":"Was müsste zwischen Tempo 30 vor der Schule und einem Autoverbot in der Innenstadt alles geschehen und beschlossen werden?","rueckmeldung":[{"option":0,"text":"Ein Entweder-oder stellt zwei Möglichkeiten gegeneinander, der Nachbar reiht dagegen Schritt an Schritt. Was fehlt, ist keine dritte Wahl, sondern Belege dafür, dass jeder Schritt zwangsläufig den nächsten auslöst."},{"option":1,"text":"Das wäre ein Fehler, nur kommt er hier nicht vor: Der Nachbar sagt nichts über die Planenden als Personen, er warnt vor den Folgen der Maßnahmen. Der Schwachpunkt liegt in seiner Kette von Folgen."},{"option":2,"text":"Der Nachbar verwirft keine Warnungen, er spricht selbst eine aus. Warnungen vor Folgen sind auch nicht per se unzulässig; seine trägt nur nicht, weil er keinen Übergang der Kette begründet."}],"familie":"dammbruch-pruefen","fertigkeit":"F2"},{"id":"qx-d1-032","clusterId":"D","werkstueckRef":"D.2.4","stufe":2,"question":"Vier Personen warnen vor einer Entwicklung. Welche Warnung ist ein stichhaltiges Kausalargument und kein Dammbruch-Fehlschluss?","options":["„Wenn wir die Zensur eindeutiger Hassrede erlauben, wird die Regierung unweigerlich politische Kritik verbieten und am Ende alle Bücher verbrennen.“","„Wenn du bei Glatteis 100 km/h fährst, ist die Wahrscheinlichkeit hoch, dass du die Kontrolle verlierst und einen schweren Unfall baust.“","„Eine befristete Lockdown-Maßnahme ist der erste Schritt zur dauerhaften Enteignung und zur Versklavung durch eine globale Elite.“","„Wenn du diesen einen Zweifel zulässt, wird der Teufel Besitz von dir ergreifen, und du endest in ewiger Verdammnis.“"],"correctIndex":1,"explanation":"Die Glatteis-Warnung ist eine Wahrscheinlichkeitsaussage: Sie basiert auf Physik und Statistik, und die Kette ist probabilistisch und belegt. Die Warnung behauptet nur ein erhöhtes Risiko, keine Gewissheit. Die anderen drei Warnungen behaupten, dass die Kette unweigerlich bis zur Katastrophe läuft, und liefern für keinen einzelnen Übergang einen Beleg. Sie übergehen auch alle Bremsen, die in der Realität dazwischenstehen, etwa Gerichte, Verfassung, Gewaltenteilung, öffentlichen Protest oder die menschliche Vernunft. Entscheidend ist also nicht die Wenn-dann-Form, sondern ob eine Wahrscheinlichkeit belegt oder eine Zwangsläufigkeit nur behauptet wird.","coreRule":"⚡ Eine belegte Wahrscheinlichkeit ist eine Warnung – eine behauptete Zwangsläufigkeit ist Panikmache.","beleg":"Werkstück D.2.4 (Kontext & Tiefe: legitimes Kausalargument vs. Fehlschluss; Anwendung & Relevanz)","status":"entwurf","scenario":"In einer Diskussionsrunde fallen vier Wenn-dann-Warnungen. Du sollst entscheiden, welche davon ernst zu nehmen ist und welche nur Angst erzeugt.","kurz":"Die Glatteis-Warnung stützt sich auf Physik und Statistik und behauptet nur ein erhöhtes Risiko. Ein Dammbruch-Fehlschluss behauptet dagegen eine Zwangsläufigkeit, ohne die einzelnen Übergänge zu belegen. Nicht die Wenn-dann-Form entscheidet, sondern der Beleg.","prueffrage":"Welche der vier Folgen ließe sich an Beobachtungen oder Unfallzahlen überprüfen?","rueckmeldung":[{"option":0,"text":"Dass Zensur missbraucht werden kann, ist ein berechtigtes Risiko. Die Warnung behauptet aber, es laufe „unweigerlich“ bis zur Bücherverbrennung, ohne einen einzigen Übergang zu belegen und ohne Gerichte, Verfassung oder Protest zu berücksichtigen."},{"option":2,"text":"Vorübergehende Maßnahmen werden manchmal verlängert, das macht die Sorge greifbar. Zwischen Lockdown, Enteignung und „Versklavung“ fehlt aber jeder belegte Zwischenschritt, und Befristung, Gerichte und Wahlen bleiben unbeachtet."},{"option":3,"text":"Die Folge wiegt so schwer, dass man sie lieber nicht prüft, und davon lebt die Warnung. Sie behauptet eine zwangsläufige Kette bis zur ewigen Verdammnis, ohne einen Übergang zu belegen, und nutzt die Angst, um Zweifel zu unterbinden."}],"familie":"dammbruch-pruefen","fertigkeit":"F2"},{"id":"qx-d1-033","clusterId":"D","werkstueckRef":"D.2.4","stufe":3,"question":"Woran erkennst du, dass aus einer berechtigten Warnung ein Fehlschluss geworden ist?","scenario":"In einer Debatte über neue Technik sagt jemand zuerst: „Ich befürchte, das könnte das Risiko für Missbrauch erhöhen.“ Später heißt es: „Das wird unweigerlich zu totaler Überwachung führen!“","options":["Daran, dass die befürchtete Folge sehr schwerwiegend ist, denn schwere Folgen machen jedes Argument unseriös.","Daran, dass aus „könnte erhöhen“ ein „wird unweigerlich führen“ wird, denn damit ersetzt Zwangsläufigkeit die Wahrscheinlichkeit.","Daran, dass die Kette der Folgen mehr als drei Glieder hat, denn erst ab dieser Länge spricht man von einem Fehlschluss.","Daran, dass die Warnung von jemandem kommt, der Veränderungen grundsätzlich ablehnt, denn dann entscheiden allein die Motive."],"correctIndex":1,"explanation":"Eine Warnung benennt ein Risiko: Etwas könnte wahrscheinlicher werden, und das lässt sich mit Belegen prüfen. Kippt sie in „wird unweigerlich“, wird eine Möglichkeit als Gewissheit ausgegeben, obwohl Bremsklötze wie Gesetze, Gerichte oder öffentliche Proteste die Kette unterbrechen können. Wie schwer die befürchtete Folge wiegt, entscheidet nicht über die Seriosität: Ein Dammbruch-Argument ist umso stärker, je wahrscheinlicher und gewichtiger die Folge ist (Hahn und Oaksford, 2006). Auch die Länge der Kette ist kein Maßstab: Eine lange Kette ist nur ein Warnzeichen, keine feste Schwelle. Entscheidend ist der Übergang von Wahrscheinlichkeit zu Zwangsläufigkeit, und der Blick auf die Motive der Sprecherin ersetzt keine Prüfung der Belege für die Übergänge.","coreRule":"⚡ „Könnte erhöhen“ ist eine Warnung, „wird unweigerlich“ ein Alarmruf ohne Beleg.","beleg":"Werkstück D.2.4 (Der Kipppunkt); Fn. gl-d-hahn (Hahn/Oaksford 2006, Informal Logic 26(1), S. 6–7)","status":"entwurf","kurz":"Der Fehlschluss beginnt, wo aus „könnte erhöhen“ ein „wird unweigerlich führen“ wird: Eine prüfbare Möglichkeit wird als Gewissheit ausgegeben, obwohl Gesetze, Gerichte oder Proteste die Kette unterbrechen können.","prueffrage":"Was könnte zwischen der neuen Technik und totaler Überwachung noch dazwischenkommen, und lässt die zweite Aussage dafür Raum?","rueckmeldung":[{"option":0,"text":"Schwere Folgen machen eine Warnung gewichtig, nicht unseriös: Je wahrscheinlicher und gewichtiger die Folge, desto stärker das Argument. Maßgeblich ist, ob aus einer Möglichkeit eine Gewissheit gemacht wird, nicht wie gravierend das Befürchtete ist."},{"option":2,"text":"Lange Ketten sind ein Warnzeichen, weil mit jedem weiteren Glied die Wahrscheinlichkeit der ganzen Kette sinkt. Eine feste Grenze wie „mehr als drei“ gibt es aber nicht, und auch eine kurze Kette kippt, wenn „könnte“ zu „wird unweigerlich“ wird."},{"option":3,"text":"Ein Blick auf die Motive kann Anlass sein, genauer hinzusehen. Ob ein Schluss trägt, zeigt sich aber an den Belegen für die einzelnen Übergänge, und die muss man auch bei einer skeptischen Person prüfen."}],"familie":"dammbruch-pruefen","fertigkeit":"F2"},{"id":"qx-d1-034","clusterId":"D","werkstueckRef":"D.2.4","stufe":4,"question":"Wie solltest du die Aussage der Kollegin beurteilen?","scenario":"Eine Kollegin meint: „Ein Dammbruch-Argument ist immer ein Fehlschluss. Die Form ‚A führt zu B, B zu C, C zu Z‘ taugt nichts.“ Du erinnerst dich an zwei Fälle: Wer bei Glatteis mit 100 km/h fährt, riskiert einen schweren Unfall. Wer behauptet, eine um eine Stunde verlängerte Sperrstunde führe „unweigerlich“ in die „24-Stunden-Anarchie“, nennt dagegen keinerlei Belege.","options":["Sie ist im Recht, weil jede Schlussform, die von heutigen Handlungen auf künftige Folgen schließt, unabhängig von ihrem Inhalt ungültig ist.","Sie ist zu pauschal, weil ein solches Argument umso stärker wird, je wahrscheinlicher und gewichtiger die befürchtete Folge ist.","Sie ist im Recht, weil sich Aussagen über künftige Ereignisse grundsätzlich nicht belegen lassen und Folgenketten daher als Argument nichts taugen.","Sie ist zu pauschal, weil nur Fachleute lange Ketten von Folgen sicher beurteilen können und deshalb allein sie damit argumentieren dürfen."],"correctIndex":1,"explanation":"Die Form „A führt zu B, B zu C“ ist an sich weder gut noch schlecht, entscheidend ist der Inhalt. Die Warnung vor dem Glatteis-Unfall stützt sich auf Physik und Statistik: Die Folge ist wahrscheinlich und schwerwiegend, also trägt das Argument. Die Sperrstunden-Rede behauptet dagegen Zwangsläufigkeit ohne Beleg für einen einzigen Übergang und ignoriert alle Bremsen im System. Auch die Argumentationsforschung (Hahn und Oaksford) kommt zu diesem Ergebnis: Ein Dammbruch-Argument ist umso stärker, je realer die Chance der befürchteten Folge ist, und es lassen sich ausdrücklich „perfectly acceptable examples“ bilden. Klassische Fehlschlüsse sind Argumentformen, die je nach Inhalt unterschiedlich stark sein können. Der Fehler liegt in der behaupteten Zwangsläufigkeit: Eine Möglichkeit wird als Gewissheit dargestellt, und für die Übergänge fehlen die Belege. Er liegt nicht schon in der Wenn-dann-Form. Ebenso falsch wäre der Gegenschluss, jede Folgenwarnung sei gültig: Prüfe jeden Übergang einzeln.","coreRule":"⚡ Ob eine Folgenwarnung trägt, entscheidet ihr Inhalt (Wahrscheinlichkeit, Gewicht, Belege für jeden Übergang), nicht ihre Wenn-dann-Form.","beleg":"Werkstück D.2.4 (Kernidee; Red Flags); Fn. gl-d-hahn (Hahn/Oaksford 2006, Informal Logic 26(1), S. 6–7; 2007, Psychological Review 114(3), S. 704–732)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Ob eine Folgenkette trägt, hängt vom Inhalt ab: Beim Glatteis ist der Unfall wahrscheinlich und schwerwiegend, bei der Sperrstunde wird Zwangsläufigkeit nur behauptet. Der Denkfehler liegt in der unbelegten Gewissheit, nicht in der Wenn-dann-Form.","prueffrage":"Haben die Glatteis-Warnung und die Sperrstunden-Rede dieselbe Form, und sind sie gleich gut begründet?","rueckmeldung":[{"option":0,"text":"Eine Schlussform allein entscheidet nicht über die Gültigkeit, sonst wäre schon die Warnung vor Glatteis wertlos. Ob ein Folgenargument trägt, hängt vom Inhalt ab: davon, wie gut die einzelnen Übergänge gestützt sind."},{"option":2,"text":"Unsicher ist Künftiges tatsächlich, und die Sperrstunden-Rede bleibt jeden Beleg schuldig. Prognosen lassen sich aber stützen: Physik und Unfallstatistik machen den Glatteis-Unfall wahrscheinlich. Nicht jede Folgenkette ist deshalb wertlos."},{"option":3,"text":"Lange Ketten sind oft schwer zu überblicken, und Fachwissen hilft beim Prüfen. Wer argumentieren darf, hängt daran aber nicht: Das Glatteis-Beispiel versteht jeder. Maßgeblich bleibt, ob die einzelnen Übergänge belegt sind."}],"familie":"dammbruch-pruefen","fertigkeit":"F2"},{"id":"qx-d1-035","clusterId":"D","werkstueckRef":"D.2.5","stufe":2,"question":"Was spricht am stärksten gegen die Behauptung, solche Wendungen seien bloßer Sprachschmuck?","scenario":"Zwei Kollegen sprechen über eine Teamsitzung. Die eine sagt: „Er hat meine Position angegriffen, ich habe mich gut verteidigt, und am Ende habe ich die Debatte gewonnen.“ Der andere widerspricht: „Das ist doch nur Wortwahl. Sprache ist Schmuck, am Denken ändert sich nichts, wenn man ein anderes Wort benutzt.“","options":["Solche Wendungen sind so alltäglich, dass sie das Denken über Argumentieren unbemerkt als Kampf prägen, ohne als Bilder aufzufallen.","Solche Wendungen verraten, dass die Sprecherin ihr Gegenüber einschüchtern will, und diese Absicht lenkt dann das Denken der Zuhörer.","Solche Wendungen sind vor allem in der Politik verbreitet, weil sie dort gezielt eingesetzt werden, um Zustimmung zu erzeugen.","Solche Wendungen lassen sich jederzeit durch wörtliche Ausdrücke ersetzen, sobald man sich ihrer bewusst geworden ist."],"correctIndex":0,"explanation":"Wenn wir eine Position „verteidigen“, ein Argument „angreifen“ oder eine Debatte „gewinnen“, übertragen wir die Struktur eines Kampfes auf ein Gespräch. Solche Metaphern sind in der Alltagssprache so selbstverständlich, dass wir sie meist nicht mehr als Bilder bemerken und oft gar keine wörtliche Alternative zur Hand haben. Gerade deshalb sind sie kein austauschbarer Schmuck: Sie prägen im Hintergrund mit, was wir an einer Sache wahrnehmen (Gegner, Sieg, Niederlage). Dass Metaphern das Urteil lenken können, deutet ein Experiment von 2011 an: Derselbe Bericht über steigende Kriminalität führte zu deutlich mehr Zustimmung zu repressiven Maßnahmen, wenn Kriminalität als wildes Tier beschrieben wurde, als wenn sie als Virus beschrieben wurde (74 % gegenüber 56 %), obwohl die Fakten identisch waren und fast niemand das Bild als Ursache nannte. Dieses Experiment hatte allerdings keine Vergleichsgruppe ohne Metapher, und eine Wiederholung der Nachfolgestudie von 2013 fand 2014 keinen Metaphern-Effekt; die Größe und Robustheit des Effekts sind also umstritten. Die Wirkung setzt nicht voraus, dass die Metapher bewusst bemerkt wird: In der Nachfolgestudie von 2013 zeigte sich der Effekt sogar bei Personen, die sich an das Bild nicht mehr erinnerten.","coreRule":"⚡ Wir benutzen die Bilder der Sprache, und sie benutzen unser Denken.","beleg":"Werkstück D.2.5 (Kontext & Tiefe); Fn. gl-d-lakoffjohnson (Lakoff/Johnson 1980; dt. Heidelberg: Carl-Auer, Kap. 1, S. 11–13, hier S. 12)","status":"entwurf","kurz":"Wendungen wie „verteidigen“ und „gewinnen“ sind so alltäglich, dass wir sie kaum als Bilder bemerken. Gerade so prägen sie mit, was wir an einem Gespräch sehen. Dass der Einfluss groß oder stabil ist, ist allerdings umstritten.","prueffrage":"Welches andere Wort würdest du für „sich verteidigen“ in diesem Gespräch einsetzen, und fällt dir überhaupt eins ein?","rueckmeldung":[{"option":1,"text":"Dass Sprache das Urteil lenken kann, ist gut denkbar. Dafür braucht es aber keine Einschüchterungsabsicht: Solche Wendungen sind so alltäglich, dass sie meist gar nicht als Bilder auffallen, und nichts im Gespräch deutet auf Absicht hin."},{"option":2,"text":"Dass Metaphern gezielt eingesetzt werden können, ist plausibel. Hier geht es aber um eine Teamsitzung und um alltägliche Wendungen, die kaum auffallen. Gegen die Schmuck-These spricht ihre unbemerkte Wirkung, nicht der Ort, an dem sie vorkommen."},{"option":3,"text":"Man kann sich eines Bildes bewusst werden und es manchmal umformulieren. Oft fehlt aber eine wörtliche Alternative, und bevor man das Bild bemerkt, hat es schon mitgeprägt, was man wahrnimmt. Zum bloßen Schmuck wird es dadurch nicht."}],"familie":"rahmen-wechseln","fertigkeit":"F2"},{"id":"qx-d1-036","clusterId":"D","werkstueckRef":"D.2.5","stufe":4,"question":"Ein Kollege schickt dir eine Schlagzeile: „Studie belegt: Ein einziges Wort im ersten Satz verändert politische Urteile um fast 20 Prozentpunkte.“ Du recherchierst: Das Experiment hatte keine Vergleichsgruppe ohne Metapher. Eine unabhängige Wiederholung einer späteren Studie derselben Forschenden fand keinen Metaphern-Effekt; schon das Lesen über Kriminalität verschob die Antworten in Richtung Polizei und Strafe, gleich welches Bild der Text benutzte. Eine Auswertung von 91 Studien fand metaphorische Rahmen wirksam, aber nur schwach. Wie sicher darfst du die Schlagzeile nehmen?","options":["Die Behauptung ist gesichert: Die Grundrichtung des Effekts ist durch mehrere Studien gestützt, also gilt auch die genannte Größe von fast 20 Prozentpunkten.","Die Behauptung ist widerlegt: Wenn eine Wiederholung keinen Effekt findet, ist die ganze Idee falsch und die Studie darf nicht mehr zitiert werden.","Die Grundrichtung ist plausibel gestützt, die genannte Größe aber unsicher: Es fehlt eine Vergleichsgruppe ohne Metapher, und die Befunde streuen zwischen stark und kaum vorhanden.","Die Behauptung lässt sich gar nicht beurteilen: Solange nicht alle Studien übereinstimmen, ist jede Aussage über den Effekt gleich viel wert."],"correctIndex":2,"explanation":"Ein Befund wird nicht dadurch sicher, dass er eine eindrucksvolle Zahl liefert. Hier fehlt in der Ausgangsstudie die Vergleichsgruppe ohne Metapher: Man kann nicht erkennen, ob das Bild etwas bewirkt oder ob schon das Lesen über Kriminalität die Antworten in Richtung Polizei und Strafe verschiebt. Genau das zeigte eine unabhängige Wiederholung der Folgestudie (Steen, Reijnierse und Burgers 2014): kein Metaphern-Effekt; schon das Lesen über Kriminalität verschob die Antworten in Richtung Polizei und Strafe, gleich welches Bild der Text benutzte. Eine Auswertung von 91 Studien (Brugman u. a. 2019) fand metaphorische Rahmen dagegen wirksam, aber nur schwach. Eine einzelne Replikation widerlegt nicht alles, und uneinheitliche Befunde machen nicht jede Aussage gleichwertig. Angemessen ist ein abgestuftes Urteil: Richtung plausibel, Größe und Robustheit offen.","coreRule":"⚡ Urteile über Studienbefunde abgestuft: Eine spektakuläre Zahl ohne Vergleichsgruppe und mit uneinheitlicher Replikation verdient „plausible Richtung, unsichere Größe“, weder blinden Glauben noch Totalverwurf.","beleg":"Werkstück D.2.5 (Hinweis zur Beleglage); Fn. gl-d-thibodeau (Thibodeau/Boroditsky 2011, 2013; Steen u. a. 2014, PLOS ONE 9(12), e113536; Brugman u. a. 2019, Language and Cognition 11(1), S. 41–65)","status":"entwurf","scenario":"","kurz":"Eine eindrucksvolle Zahl macht einen Befund nicht sicher: Ohne Vergleichsgruppe bleibt offen, ob das Bild wirkt oder schon das Thema. Die Befunde reichen von deutlich bis gar nicht, die Gesamtauswertung zeigt nur schwache Wirkung: Richtung plausibel, Größe offen.","prueffrage":"Was fanden die Wiederholung und die Auswertung der 91 Studien jeweils, gemessen an den fast 20 Prozentpunkten der Schlagzeile?","rueckmeldung":[{"option":0,"text":"Dass mehrere Studien eine Wirkung finden, stützt die Richtung. Von dort lässt sich aber nicht auf die Größe schließen: Die Auswertung fand den Effekt nur schwach, und die Ausgangsstudie hatte keine Vergleichsgruppe."},{"option":1,"text":"Die Wiederholung ohne Effekt und die fehlende Vergleichsgruppe sind ernste Mängel. Eine einzelne Replikation widerlegt aber nicht alles, und die Auswertung von 91 Studien fand schwache Wirkung. Weniger sicher ist nicht gleich widerlegt."},{"option":3,"text":"Uneinheitliche Befunde machen die Lage unübersichtlich. Sie machen aber nicht jede Aussage gleichwertig: Aus Qualität und Stärke der Studien lässt sich ein abgestuftes Urteil ableiten, nur eben mit offener Größe."}],"familie":"wiederholung-abwarten","fertigkeit":"F1"},{"id":"qx-d1-037","clusterId":"D","werkstueckRef":"D.2.5","stufe":2,"question":"Welche Vermutung über die Wirkung des Kampfbildes ist am wahrscheinlichsten, und warum sollte man sie vor dem Start der Kampagne prüfen?","scenario":"Eine Gesundheitskampagne will Menschen zur Krebsvorsorge bewegen. Der Slogan lautet: „Gemeinsam den Krebs bekämpfen!“ Die Verantwortlichen sind überzeugt, das Kriegsbild wecke Dringlichkeit und motiviere zum Arztbesuch. Dafür gibt es bisher keine Belege; in vier Online-Studien mit Versuchspersonen ohne Krebserkrankung wurde allerdings untersucht, wie solche Kampfbilder wirken.","options":["Das Bild lässt die Krankheit übermächtig und die Behandlung schwierig erscheinen und kann Fatalismus verstärken, ohne dass die Bereitschaft zum Arztbesuch steigt.","Das Bild steigert die Wachsamkeit und weckt Dringlichkeit, sodass die Menschen eher zur Vorsorge gehen, wie die Verantwortlichen es erhoffen.","Das Bild hat keinerlei Wirkung auf die Lesenden, weder auf ihre Einschätzung der Behandlung noch auf ihr Verhalten.","Das Bild wirkt nur bei Menschen mit eigener Erkrankung, während es bei Gesunden folgenlos bleibt und deshalb keine Prüfung braucht."],"correctIndex":0,"explanation":"Die Hoffnung, ein Kampfbild wecke Dringlichkeit, ist eine plausible, aber ungeprüfte Annahme, und gut gemeinte Bilder haben oft Nebenwirkungen. In vier Online-Studien (Hauser und Schwarz 2020) ließ die Rede vom „Kampf“ gegen den Krebs die Behandlung schwieriger erscheinen und verstärkte den Fatalismus („gegen Krebs kann man ohnehin wenig tun“); die Bereitschaft, zum Arzt zu gehen, stieg nicht. Wer ein Bild für wirksam hält, sollte also messen, was es tatsächlich bewirkt, statt es vorauszusetzen. Vorbehalt: Untersucht wurden Personen ohne Krebserkrankung; Aussagen über Betroffene lassen sich daraus nicht ableiten.","coreRule":"⚡ Auch gut gemeinte Bilder wie der „Kampf“ haben Nebenwirkungen darauf, was Menschen für möglich halten. Ob ein Bild wirkt wie erhofft, muss man prüfen, nicht annehmen.","beleg":"Werkstück D.2.5 (Anwendung & Relevanz: Gesundheitspolitik); Fn. gl-d-kampfmetapher (Hauser/Schwarz 2020, Health Communication 35(13), S. 1698–1704)","status":"entwurf","kurz":"Ob ein Kampfbild wirkt wie erhofft, ist eine Annahme, die man messen muss. In vier Online-Studien ließ es die Behandlung schwieriger erscheinen und verstärkte den Fatalismus, ohne die Bereitschaft zum Arztbesuch zu erhöhen.","prueffrage":"Woran würdest du erkennen, dass ein Slogan Menschen tatsächlich zum Handeln bringt und nicht nur gut gemeint klingt?","rueckmeldung":[{"option":1,"text":"Dass ein Kampfbild Dringlichkeit weckt, klingt einleuchtend und ist genau die Hoffnung der Verantwortlichen. Belegt ist sie aber nicht, und in den Studien stieg die Bereitschaft zum Arztbesuch nicht."},{"option":2,"text":"Keine Wirkung wäre die harmloseste Annahme, doch in den Studien gab es eine: Die Behandlung erschien schwieriger, und der Fatalismus nahm zu. Nur die erhoffte Wirkung blieb aus, die Bereitschaft zum Arztbesuch stieg nicht."},{"option":3,"text":"Die Unterscheidung nach Erkrankung ist nicht abwegig, denn untersucht wurden nur Menschen ohne Krebs. Gerade bei ihnen zeigte das Bild aber Wirkungen: Die Behandlung erschien schwieriger, der Fatalismus nahm zu. Folgenlos ist es also nicht."}],"familie":"rahmen-wechseln","fertigkeit":"F2"},{"id":"qx-d1-038","clusterId":"D","werkstueckRef":"D.2.5","stufe":3,"question":"Was ist an der Forderung der Leserin am ehesten das Problem?","scenario":"Eine Zeitung berichtet über Migration. In jedem Artikel kommen „Flut“, „Welle“ und „Dämme“ vor, die genannten Zahlen sind korrekt. In Artikeln anderer Zeitungen über dieselben Zahlen ist von „Wanderungsbewegungen“, „Arbeitskräften“ oder einzelnen Lebensläufen die Rede. Eine Leserin sagt: „Naturbilder für Menschen sind grundsätzlich unzulässig, jede Zeitung müsste sie verbieten.“","options":["Sie verlangt ein Verbot von Bildern, obwohl jede Sprache über Migration irgendein Bild braucht; problematisch wird nur ein einziges Bild ohne Alternativen.","Sie übersieht, dass korrekte Zahlen im Text den Einfluss eines Bildes vollständig aufheben; ein Verbot ist daher überflüssig.","Sie übersieht, dass Leser ein lenkendes Bild sofort bemerken; deshalb braucht es keinen Schutz davor.","Sie verkennt, dass Naturbilder für Menschen nur irreführen, wenn die berichteten Zahlen falsch sind."],"correctIndex":0,"explanation":"Metaphern sind ein unvermeidbares Werkzeug des Denkens: Abstraktes lässt sich ohne Bilder kaum beschreiben, also kann es nicht darum gehen, Bilder zu verbieten. Problematisch wird ein Bild, wenn es zur einzigen Linse wird. Eine Naturkatastrophen-Metapher lässt Menschen unbemerkt als unpersönliche Naturgewalt erscheinen, gegen die man „Dämme“ baut, statt zu verhandeln, und Alternativen wie Wanderungsbewegung, Lebensläufe oder Arbeitsmarktfrage verschwinden aus dem Text. Dass Bilder auch bei korrekten Zahlen lenken, zeigte ein Experiment von Thibodeau und Boroditsky (2011): Bei identischer Kriminalstatistik unterschied sich die Zustimmung zu repressiven Maßnahmen je nach Tier- oder Virus-Bild um rund 18 Prozentpunkte, und fast niemand nannte die Metapher als Einflussfaktor. (Die genaue Größe und Robustheit des Effekts ist umstritten; seine Grundrichtung gilt aber als durch mehrere Studien gestützt.) Zu prüfen ist deshalb, ob es Alternativen zum Bild gibt und ob es offengelegt wird.","coreRule":"⚡ Nicht das Bild ist das Problem, sondern ein Bild ohne Alternative.","beleg":"Werkstück D.2.5 (Der Kipppunkt; Anwendung & Relevanz: Die eigene Argumentation)","status":"entwurf","kurz":"Ein Verbot geht am Problem vorbei, denn über Migration lässt sich kaum ohne irgendein Bild sprechen. Kritisch wird ein Bild erst, wenn es ohne Alternativen als einzige Linse steht und Menschen wie eine Naturgewalt erscheinen lässt.","prueffrage":"Welche anderen Wörter benutzen andere Zeitungen für dieselben Zahlen, und was zeigen sie anders?","rueckmeldung":[{"option":1,"text":"Zahlen im Text scheinen ein Gegengewicht zum Bild zu bilden. Im Experiment mit identischer Kriminalstatistik unterschied sich die Zustimmung trotzdem je nach Bild: Korrekte Zahlen heben den Einfluss eines Bildes nicht einfach auf."},{"option":2,"text":"Wörter wie „Flut“ fallen zwar auf, ihre lenkende Wirkung aber kaum: Im Experiment mit identischer Kriminalstatistik nannte fast niemand die Metapher als Einflussfaktor, obwohl die Zustimmung je nach Bild verschieden ausfiel."},{"option":3,"text":"Korrekte Zahlen schließen eine Täuschung durch Zahlen aus, aber keine Lenkung durch Bilder: In einem Experiment mit identischer Kriminalstatistik fiel die Zustimmung je nach Bild verschieden aus. Heikel wird ein Bild, wenn es die einzige Linse ist."}],"familie":"rahmen-wechseln","fertigkeit":"F2"},{"id":"qx-d1-039","clusterId":"D","werkstueckRef":"D.3.1","stufe":1,"question":"Welche Schlussfolgerung ist hier am sinnvollsten?","scenario":"Eine Politikerin fordert in einer Rede, man müsse sich endlich um die „hart arbeitenden Familien in den Vorstädten“ und ihre „Werte“ kümmern. Ein Kommentator wirft ihr vor, sie sende damit verdeckt eine Botschaft an ihre Kernanhänger. Sie entgegnet empört: „Ich habe doch nur von Familien gesprochen! Wieso unterstellst du mir böse Absichten?“ Auffällig ist: Ihre Stammwählerschaft reagiert auf genau diese Formulierungen jedes Mal besonders begeistert, viele andere Zuhörer nehmen sie als Standardfloskel wahr.","options":["Weil die Formulierung für die Allgemeinheit harmlos klingt, ist ausgeschlossen, dass sie für die Stammwählerschaft eine zusätzliche Bedeutung trägt.","Weil die Empörung der Politikerin so heftig ausfällt, ist damit bewiesen, dass sie keinerlei verdeckte Botschaft senden wollte.","Die wörtliche Bedeutung allein entscheidet nichts: Man sollte prüfen, welche Assoziationen die Wörter bei der Zielgruppe wecken, und ob sich diese Deutung im Zusammenhang belegen lässt.","Weil die Stammwählerschaft begeistert reagiert, ist bewiesen, dass die Politikerin ihre Botschaft gezielt als geheimen Code für Eingeweihte konstruiert hat."],"correctIndex":2,"explanation":"Eine Botschaft kann auf zwei Kanälen laufen: für die Allgemeinheit harmlos, für Eingeweihte mit zusätzlicher Bedeutung. Das nennt man „Dog Whistling“ (Hundepfeife): Der hohe Ton einer Hundepfeife ist für Menschen unhörbar, für Hunde aber klar wahrnehmbar. Die Sprecherin gewinnt dadurch „plausible Abstreitbarkeit“ (plausible deniability): Sie kann auf den harmlosen Wortlaut verweisen. Die Wörter sind nur der Träger, die Assoziationen im Kopf des Empfängers sind die eigentliche Botschaft. Deshalb taugt weder die Harmlosigkeit des Wortlauts noch die Empörung der Sprecherin als Gegenbeweis. Aber auch die begeisterte Reaktion der Anhänger beweist die Absicht noch nicht, sie ist nur ein Hinweis. Ob wirklich ein Code vorliegt, zeigt sich an Anzeichen wie wiederholter Verwendung, starker Reaktion der Anhänger und dem Kontext bzw. der Geschichte der Phrase.","coreRule":"⚡ Die Botschaft steckt nicht allein im Wort, sondern in dem, was die Eingeweihten darin hören; prüfe darum immer, welchen Code eine Zielgruppe hören könnte und was sich dafür belegen lässt.","beleg":"Werkstück D.3.1 (Kernidee; Kontext & Tiefe)","status":"entwurf","kurz":"Der Wortlaut allein entscheidet nichts, denn die Wörter sind nur Träger, die Botschaft steckt in den Assoziationen der Zielgruppe. Ob wirklich ein Code vorliegt, zeigt sich erst im Kontext und in der Geschichte der Phrase.","prueffrage":"Was weißt du über die Absicht der Politikerin sicher, und was schließt du nur aus Reaktionen oder Beteuerungen?","rueckmeldung":[{"option":0,"text":"Ein harmloser Wortlaut für die Allgemeinheit schließt eine zweite Bedeutung nicht aus. Gerade das ist das Kennzeichen einer Botschaft auf zwei Kanälen: Dieselben Wörter wecken bei Eingeweihten zusätzliche Assoziationen."},{"option":1,"text":"Empörung kann echt sein, sagt aber nichts darüber, welche Assoziationen die Wörter wecken. Wer verdeckt sendet, kann sich ebenso empört auf den harmlosen Wortlaut berufen. Als Beweis taugt die Heftigkeit in keine Richtung."},{"option":3,"text":"Die begeisterte Reaktion der Stammwähler ist ein ernst zu nehmender Hinweis, aber noch kein Beweis, dass die Formulierung gezielt als Code gebaut wurde. Dazu gehören auch der Kontext und die bisherige Verwendung der Phrase."}],"familie":"kodierte-botschaft","fertigkeit":"F2"},{"id":"qx-d1-040","clusterId":"D","werkstueckRef":"D.3.1","stufe":2,"question":"Welche Schlussfolgerung ist aus dieser Reaktion gerechtfertigt?","scenario":"Ein Politiker spricht von „den hart arbeitenden Familien in den Vorstädten“ und „ihren Werten“. Eine Journalistin fragt, ob damit bestimmte Gruppen ausgegrenzt werden sollen. Er antwortet empört: „Ich habe doch nur von Familien gesprochen – warum legst du mir böse Dinge in den Mund?“","options":["Die empörte Zurückweisung beweist, dass keine verdeckte Botschaft vorliegt, denn wer nichts Böses meint, wehrt sich immer so.","Die empörte Zurückweisung beweist, dass die Phrase ein Code ist, denn wer sich so heftig wehrt, hat etwas zu verbergen.","Die empörte Zurückweisung zeigt nur, dass die Phrase auch harmlos lesbar ist; ob ein Code vorliegt, lässt sie offen und muss am Zusammenhang geprüft werden.","Die empörte Zurückweisung macht jede weitere Prüfung überflüssig, weil die Journalistin dem Redner Absichten unterstellt hat."],"correctIndex":2,"explanation":"Die Reaktion sagt über die Absicht des Redners wenig. Wer etwas Verdecktes meint, kann sich genau so äußern, denn eine harmlose Oberfläche erlaubt ihm, sich auf den Wortlaut zurückzuziehen und die Verantwortung für die Nebenbedeutung abzuweisen (plausible Abstreitbarkeit). Wer nichts Verdecktes meint, kann sich ebenso äußern, denn ein Unterstellungsvorwurf kann auch zu Unrecht erhoben werden. Ob die Empörung echt oder gespielt ist, lässt sich von außen kaum unterscheiden; sie ist deshalb weder Beweis noch Gegenbeweis. Ob ein Code vorliegt, zeigt erst die Prüfung am Zusammenhang, etwa an einer wiederholten Phrase mit auffällig starker Reaktion der Anhängerschaft, an einer nur Insidern verständlichen Bedeutung und an der Geschichte der Phrase.","coreRule":"⚡ Empörte Zurückweisung ist ein Warnzeichen, aber kein Beweis, weder für noch gegen eine verdeckte Botschaft.","beleg":"Werkstück D.3.1 (Einstiegsszene; Kontext & Tiefe: plausible Abstreitbarkeit; Red Flags)","status":"entwurf","kurz":"Die Reaktion sagt über die Absicht wenig, denn wer etwas Verdecktes meint, kann sich genauso äußern wie jemand ohne Hintergedanken. Der Denkfehler wäre, aus der Heftigkeit der Empörung ein Urteil abzuleiten, statt den Zusammenhang der Phrase zu prüfen.","prueffrage":"Was hat die Journalistin gefragt, und was davon beantwortet der Politiker in seiner Reaktion tatsächlich?","rueckmeldung":[{"option":0,"text":"Empörung passt zu Unschuld, denn auch ein unberechtigter Vorwurf kann sie auslösen. Sie beweist aber nichts: Wer etwas Verdecktes meint, kann sich genau so äußern und auf den Wortlaut zurückziehen."},{"option":1,"text":"Gespielte Empörung kann ein Warnzeichen sein, nur sieht man ihr das Spiel nicht an. Dieselbe Reaktion kann auch von jemandem kommen, der sich zu Unrecht verdächtigt fühlt, deshalb ist sie kein Beweis für einen Code."},{"option":3,"text":"Die Journalistin hat gefragt, nicht behauptet. Und selbst ein zu Unrecht geäußerter Verdacht klärt nicht, ob die Phrase ein Code ist; das zeigt erst die Prüfung am Zusammenhang, die eine Reaktion nicht ersetzt."}],"familie":"kodierte-botschaft","fertigkeit":"F2"},{"id":"qx-d1-041","clusterId":"D","werkstueckRef":"D.3.1","stufe":3,"question":"Woran erkennst du am besten, dass im zweiten Forum aus harmloser Insider-Sprache eine problematische Taktik geworden ist?","scenario":"In einem Forum tauschen sich Angler in ihrem Fachjargon aus, den Außenstehende nicht verstehen. In einem anderen Forum benutzen Nutzer eine scheinbar harmlose Redewendung, die unter Eingeweihten als Erkennungszeichen für Verachtung gegenüber einer Minderheit gilt. Auf Kritik antworten sie empört: „Wir haben doch nur etwas Neutrales gesagt, ihr interpretiert da etwas hinein!“","options":["Außenstehende verstehen die Redewendung nicht, was auf eine bewusst ausgrenzende Absicht hindeutet.","Die Redewendung lässt sich auf mehr als eine Weise deuten, was auf eine verdeckte Absicht hindeutet.","Die Redewendung verbreitet Vorurteile und die Berufung auf ihre Harmlosigkeit verhindert die ehrliche Debatte.","Die Redewendung stärkt den Zusammenhalt der Gruppe, was auf eine ausgrenzende Absicht hindeutet."],"correctIndex":2,"explanation":"Auch der Angler-Jargon schließt Außenstehende aus und ist trotzdem unproblematisch: Insider-Sprache unter Freunden ist harmlos, denn eigene Sprache signalisiert Zugehörigkeit. Dass Außenstehende etwas nicht verstehen, ist also kein Beleg für Böswilligkeit. Dasselbe gilt für Mehrdeutigkeit, denn viele Wörter haben mehrere Bedeutungen, und für Gruppenzusammenhalt, der fast immer mit eigener Sprache einhergeht. Entscheidend ist, was der Code tut: Er wird zur toxischen Taktik, wenn er systematisch Vorurteile verbreitet und zugleich eine ehrliche Debatte nahezu unmöglich macht. Die gespielte Empörung auf Kritik schützt den Sprecher dabei vor Verantwortung. Dann ist aus Gruppenkultur eine Taktik der plausiblen Abstreitbarkeit geworden.","coreRule":"⚡ Ein Code unter Freunden ist Gruppenkultur; ein Code, der Vorurteile tarnt und Kritik mit „Ich habe doch nichts gesagt“ abwehrt, ist eine Taktik.","beleg":"Werkstück D.3.1 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Entscheidend ist, was die Redewendung tut: Sie verbreitet Vorurteile, und die empörte Berufung auf ihre Harmlosigkeit blockiert die Debatte. Dass Außenstehende sie nicht verstehen, taugt nicht als Maßstab, denn das gilt auch für harmlosen Jargon.","prueffrage":"Welche Merkmale teilt die Redewendung mit dem Angler-Jargon, und worin unterscheidet sie sich von ihm?","rueckmeldung":[{"option":0,"text":"Dass Außenstehende etwas nicht verstehen, wirkt wie ein Warnsignal, trifft aber ebenso auf den Angler-Jargon zu. Als Merkmal trennt es die beiden Foren nicht, und aus Unverständlichkeit allein lässt sich keine böse Absicht ableiten."},{"option":1,"text":"Mehrere Deutungen zu haben, ist bei Wörtern völlig normal und zeigt noch keine verdeckte Absicht. Entscheidend ist, was die Wendung bewirkt: ob sie Vorurteile transportiert und Kritik an ihr abgewehrt wird."},{"option":3,"text":"Eigene Sprache geht fast immer mit Gruppenzusammenhalt einher, auch unter Anglern, und ist für sich genommen harmlos. Ob eine Wendung schadet, zeigt sich daran, was sie bewirkt: ob sie Vorurteile verbreitet und Kritik abblockt."}],"familie":"kodierte-botschaft","fertigkeit":"F2"},{"id":"qx-d1-042","clusterId":"D","werkstueckRef":"D.3.1","stufe":4,"question":"Welcher Schluss ist aus dem Aufbau dieses Experiments am besten begründet?","scenario":"Ein Kandidat dreht ein Wahlvideo. Im letzten Satz will er eine Wendung aus einem Kirchenlied einbauen, die nur Menschen aus bestimmten Pfingstgemeinden als Anspielung erkennen. Ein Berater warnt: „Wenn wir das so sagen, verprellen wir alle anderen.“ Ein zweiter Berater hält dagegen: „Dann sagen wir es offen dazu: ‚As I sing in church‘.“ Ein Experiment mit US-Wählern hat genau diese beiden Fassungen verglichen.","options":["Die verdeckte Anspielung kann bei Eingeweihten gut ankommen, ohne Außenstehende messbar abzuschrecken; die offen religiöse Fassung ist dagegen riskanter.","Die verdeckte Anspielung schreckt Außenstehende messbar ab, während die offen religiöse Fassung bei allen Gruppen unauffällig bleibt.","Verdeckte Anspielungen bleiben ohne jede Wirkung, weil Menschen Botschaften, die sie nicht bewusst bemerken, auch nicht verarbeiten.","Eine verdeckte Anspielung kann nur wirken, wenn alle Zuschauer sie bewusst bemerken und als gezielte Botschaft erkennen."],"correctIndex":0,"explanation":"Entscheidend ist, wer die Anspielung überhaupt bemerkt. Wer die Wendung kennt, hört die Botschaft und bewertet den Kandidaten besser. Wer sie nicht kennt, hört einen gewöhnlichen Satz und hat keinen Anlass, sich zu stören. Der offene Zusatz dagegen ist für alle sofort als religiöse Aussage erkennbar und senkte in der gemischten Stichprobe Eindruck und Wahlabsicht. Genau so fiel das Ergebnis des Experiments (Albertson 2015) aus: Bei Pfingstlern, die das Lied kannten, verbesserte die Anspielung den Eindruck vom Kandidaten, ohne die Zuschauer einer gemischten Stichprobe messbar abzuschrecken; derselbe Satz mit offen religiösem Zusatz tat das sehr wohl. Die Gegenvarianten scheitern jeweils an einem Denkfehler: Die Anspielung musste von Außenstehenden nicht bemerkt werden, um bei Eingeweihten zu wirken, und die offene Fassung ist gerade nicht unauffällig. Vorbehalt: Es war ein Versuch mit religiöser Sprache in den USA; gemessen wurden Eindruck und Wahlabsicht, die Übertragung auf andere Anspielungen ist eine Annahme.","coreRule":"⚡ Wirkt eine Anspielung nur bei denen, die sie verstehen, stört sie die anderen nicht: Nicht bemerkt heißt nicht wirkungslos.","beleg":"Werkstück D.3.1 (Anwendung & Relevanz: In der Politik); Fn. gl-d-albertson. Albertson, B. L. (2015): Dog-Whistle Politics: Multivocal Communication and Religious Appeals. Political Behavior 37(1), 3–26, https://doi.org/10.1007/s11109-013-9265-x (Stichprobe 1: 402 Pfingstchristen, 84 % kannten die Wendung „wonder-working power“; Stichprobe 2: 783 Befragte, ohne die 24 %, die sie kannten; offener Zusatz „As I sing in church“; gelesen 12.10.2026 im Volltext, S. 9–14).","status":"entwurf","kurz":"Wer die Wendung kennt, hört die Botschaft und bewertet den Kandidaten besser; wer sie nicht kennt, hört einen gewöhnlichen Satz und stört sich nicht. Der offene Zusatz ist dagegen für alle erkennbar und senkte Eindruck und Wahlabsicht.","prueffrage":"Welche Zuschauer können in jeder der beiden Fassungen überhaupt merken, dass hier eine religiöse Aussage fällt?","rueckmeldung":[{"option":1,"text":"Dass ein verstecktes Signal mehr Ärger birgt als ein offenes, klingt plausibel. Gemessen wurde aber das Gegenteil: Der verdeckte Satz schreckte Außenstehende nicht messbar ab, der offen religiöse Zusatz senkte dagegen Eindruck und Wahlabsicht."},{"option":2,"text":"Richtig ist, dass Außenstehende die Anspielung nicht bemerken und deshalb nicht darauf reagieren. Daraus folgt aber keine Wirkungslosigkeit: Bei Pfingstlern, die das Lied kannten, verbesserte sie den Eindruck vom Kandidaten."},{"option":3,"text":"Eine Anspielung muss nicht alle erreichen, um zu wirken. Außenstehende überhörten sie und wurden nicht messbar abgeschreckt, und bei Eingeweihten, die das Lied kannten, kam sie gut an."}],"familie":"kodierte-botschaft","fertigkeit":"F2"},{"id":"qx-d1-043","clusterId":"D","werkstueckRef":"D.3.2","stufe":1,"question":"Wie reagierst du am klügsten auf diesen Gesprächsverlauf?","scenario":"In einer Diskussion über Staatsfinanzen sagt jemand: „Alle Steuern sind Diebstahl. Der Staat nimmt den Menschen mit Gewalt, was ihnen gehört.“ Du widersprichst und führst an, dass Straßen, Schulen und Gerichte aus Steuern bezahlt werden. Er antwortet: „Ich sage ja nur, dass die Regierung sparsam mit dem Geld der Bürger umgehen sollte. Willst du etwa Verschwendung verteidigen?“ Du merkst, dass du dem zweiten Satz kaum widersprechen kannst.","options":["Du stimmst zu, dass sparsames Haushalten wichtig ist, und fragst, ob er weiterhin hinter seiner ersten Aussage steht, dass alle Steuern Diebstahl sind.","Du erklärst ihm ausführlich, dass die Regierung gar nicht verschwenderisch wirtschaftet, und belegst das mit Haushaltszahlen aus den letzten Jahren.","Du wirfst ihm vor, in Wahrheit gar nicht sparsam zu denken, und fragst, welche Ausgaben er persönlich für überflüssig hält.","Du räumst ein, dass seine erste Aussage vielleicht zu scharf war, und beendest das Gespräch, weil ihr euch im Kern ohnehin einig seid."],"correctIndex":0,"explanation":"Der Sprecher hat zwei Aussagen gemacht, die verschieden stark sind: eine radikale („Alle Steuern sind Diebstahl“), die schwer zu verteidigen ist, und eine harmlose („sparsam umgehen“), der fast jeder zustimmt. Unter Druck weicht er auf die harmlose aus und tut so, als habe er nie mehr gesagt. Wer nun nur die harmlose Aussage diskutiert, greift ins Leere, und der Sprecher kehrt später unbemerkt zur starken Behauptung zurück. Klug ist es, der unstrittigen Aussage ehrlich zuzustimmen und dann zur ursprünglichen, starken Behauptung zurückzuführen: „Stehst du noch zu deiner ersten Aussage?“ Dann muss er sich entscheiden. Entweder er verteidigt die radikale Aussage und trägt die argumentativen Kosten, oder er nimmt sie zurück. Beides ist ein ehrliches Ergebnis. Dieses Muster ist als Motte-and-Bailey-Täuschung bekannt (benannt nach der mittelalterlichen Burg: schwer zu verteidigende Vorburg, gut zu haltender Turmhügel; geprägt vom Philosophen Nicholas Shackel 2005). Ob die Regierung tatsächlich sparsam wirtschaftet, ist eine andere Frage und löst das Problem des Positionswechsels nicht.","coreRule":"⚡ Stimm der harmlosen Aussage zu, aber bring das Gespräch zur ursprünglichen, starken Behauptung zurück und lass sie bestätigen oder zurücknehmen.","beleg":"Werkstück D.3.2 (Kontext & Tiefe); Fn. gl-d-shackel (Shackel 2005, Metaphilosophy 36(3), S. 295–320)","status":"entwurf","kurz":"Stimm der unstrittigen Aussage zu und führ dann zur starken zurück: „Stehst du noch zu deiner ersten Aussage?“ So muss er sich entscheiden. Wer nur die harmlose Aussage diskutiert, greift ins Leere.","prueffrage":"Worüber habt ihr am Anfang gestritten, und worüber würdet ihr nach seiner Antwort streiten?","rueckmeldung":[{"option":1,"text":"Mit Haushaltszahlen zeigst du ihm zwar ein echtes Thema, aber nicht das ursprüngliche. Ob die Regierung sparsam wirtschaftet, lässt die Behauptung „Alle Steuern sind Diebstahl“ unberührt, und er kann unbemerkt zu ihr zurückkehren."},{"option":2,"text":"Die Nachfrage nach überflüssigen Ausgaben klingt nach Klärung. Sie bleibt aber bei der harmlosen Aussage, und die Unterstellung, er denke gar nicht sparsam, ist unbelegt und lenkt von der starken Behauptung ab."},{"option":3,"text":"Ein Zugeständnis wirkt fair und entspannt das Gespräch. Doch ihr seid euch im Kern nicht einig: Er hat die Aussage über Diebstahl nie zurückgenommen, sondern ist nur ausgewichen. Mit dem Abbruch bleibt sie unbeantwortet stehen."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2"},{"id":"qx-d1-044","clusterId":"D","werkstueckRef":"D.3.2","stufe":2,"question":"Wie reagierst du am klügsten?","scenario":"Dein Gegenüber behauptet: „Homöopathie kann Grippe heilen.“ Du fragst nach Belegen. Er antwortet: „Ich sage ja nur, dass es den Placebo-Effekt wirklich gibt.“ Kurz darauf redet er wieder davon, dass man mit Homöopathie auf Medikamente gegen die Grippe verzichten könne.","options":["Der vernünftigen Aussage über den Placebo-Effekt zustimmen und ihn dann fragen, ob er weiterhin zu seiner ursprünglichen Heilungsbehauptung steht.","Auch die Aussage über den Placebo-Effekt bestreiten und ihm vorhalten, dass jede Abschwächung einer Behauptung ein Zeichen von Unehrlichkeit ist.","Das Gespräch beenden, weil sein Rückzug zeigt, dass er sich der Schwäche seiner eigenen Position längst bewusst ist.","Die Aussage über den Placebo-Effekt als bloßes Ausweichmanöver abtun und ohne weitere Rückfrage mit weiteren Studien gegen die Heilungsbehauptung argumentieren."],"correctIndex":0,"explanation":"Hier wechselt jemand von einer starken, schwer zu belegenden Behauptung („heilt Grippe“) zu einer harmlosen, kaum bestreitbaren („den Placebo-Effekt gibt es wirklich“) und kehrt später zur starken zurück. Dieses Muster heißt Motte-and-Bailey, nach der mittelalterlichen Burg mit schwer haltbarem Vorhof (Bailey) und gut zu verteidigendem Turmhügel (Motte). Die harmlose Aussage zu bekämpfen führt ins Leere: Sie ist vernünftig und weithin akzeptiert, und gegen sie lässt sich kaum argumentieren. Der Ausweg ist, ihr zuzustimmen und die ursprüngliche Behauptung festzunageln („Pinning Down the Bailey“): „Stehst du noch zu deiner ersten Aussage?“ So muss er sich entscheiden. Entweder er verteidigt die starke Behauptung und muss Belege liefern, oder er gibt sie offen auf. Eine Meinung im Gespräch abzuschwächen ist ein Zeichen intellektueller Ehrlichkeit. Motte-and-Bailey ist das Gegenteil, weil der Rückzug nur ein Fluchtweg ist und die radikale Position danach unauffällig zurückkehrt. Auch das Gespräch abzubrechen hilft nicht: Der Rückzug sagt nichts darüber, was er selbst glaubt, und die Behauptung bliebe unwidersprochen im Raum.","coreRule":"⚡ Stimm der harmlosen Aussage zu und frag nach der starken.","beleg":"Werkstück D.3.2 (Das Anti-Denkmuster; Anwendung & Relevanz: Pseudomedizin & Esoterik)","status":"entwurf","kurz":"Mit dem Placebo-Effekt weicht er auf eine viel schwächere Aussage aus, die deine Frage nach Belegen nicht beantwortet, und kehrt danach zur Heilungsbehauptung zurück. Stimm dem Placebo-Satz zu und frag, ob er noch zu ihr steht: Dann muss er Belege liefern oder sie aufgeben.","prueffrage":"Wie verhält sich der Satz über den Placebo-Effekt zu dem, was er vorher und nachher über Homöopathie sagt?","rueckmeldung":[{"option":1,"text":"Die Placebo-Aussage zu bestreiten, lenkt vom eigentlichen Streitpunkt ab, der Heilungsbehauptung. Abschwächen ist zudem oft ehrlich; zum Fluchtweg wird es hier nur, weil die starke Behauptung danach wiederkehrt."},{"option":2,"text":"Das Gespräch zu beenden wirkt konsequent. Der Rückzug sagt aber nichts darüber, was er wirklich glaubt, und die Heilungsbehauptung bliebe unwidersprochen stehen."},{"option":3,"text":"Von einem Ausweichen zu sprechen, ist nicht falsch gedacht. Ohne Rückfrage bleibt er aber nicht auf die Heilungsbehauptung festgelegt und kann sich erneut auf die harmlose Aussage zurückziehen."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2"},{"id":"qx-d1-045","clusterId":"D","werkstueckRef":"D.3.2","stufe":3,"question":"Was ist an seinem Vorgehen fehlerhaft?","scenario":"Ein Kollege behauptet im Meeting: „Unser neues Lernprogramm macht jeden Mitarbeiter innerhalb einer Woche zum Top-Verkäufer.“ Du fragst nach Belegen. Er antwortet: „Ich habe nur gesagt, dass Weiterbildung grundsätzlich sinnvoll ist.“ Du stimmst zu. Kurz darauf wirbt er im Team wieder dafür, dass das Programm jeden zum Top-Verkäufer macht.","options":["Er hat seine Position abgeschwächt, und wer nachgibt, argumentiert schwach, weil Beständigkeit stets für Ehrlichkeit spricht.","Er hat sich nur zum Schein auf die harmlose Aussage zurückgezogen und die kühne Behauptung danach wieder vertreten, als wäre nichts gewesen.","Er hat eine wahre Aussage gemacht, und wer Wahres sagt, tarnt damit zwangsläufig immer eine falsche Behauptung.","Er hat die Abschwächung offen angekündigt, und wer Positionen klar trennt, verbirgt dadurch bewusst die eigentliche Absicht."],"correctIndex":1,"explanation":"Seine Behauptung hat sich nie geändert: Unter Kritik wich er auf eine leicht zu verteidigende Aussage aus, die kaum jemand bestreitet, und kehrte danach unauffällig zur kühnen Behauptung zurück. Dadurch wurde die starke Aussage nie wirklich geprüft. Eine Position abzuschwächen ist an sich ehrlich, wenn man die starke Aussage dauerhaft aufgibt. Hier wurde sie nur vorübergehend versteckt. Zum Prüfen hilft die Frage, ob er noch zur ursprünglichen Aussage steht: Wer sie bejaht, muss Belege liefern, wer sie verneint, hat sie aufgegeben. Dieses Muster heißt Motte-and-Bailey: Bei Kritik zieht man sich in die gut zu verteidigende „Motte“ zurück, die kühne „Bailey“ nimmt man später wieder ein.","coreRule":"⚡ Zurückrudern ist ehrlich, wenn die Position dauerhaft geräumt wird, nicht, wenn sie heimlich zurückkehrt.","beleg":"Werkstück D.3.2 (Kernidee; Der Kipppunkt; Red Flags)","status":"entwurf","kurz":"Seine kühne Behauptung hat er nie aufgegeben, sondern unter Kritik nur kurz gegen eine kaum bestreitbare Aussage getauscht und danach wieder vertreten. So wurde sie nie geprüft. Abschwächen ist ehrlich, wenn man die starke Aussage wirklich aufgibt.","prueffrage":"Was behauptet er im Meeting, was nach deiner Frage nach Belegen und was später im Team?","rueckmeldung":[{"option":0,"text":"Wer eine Position abschwächt, argumentiert nicht automatisch schwach, und Beständigkeit allein belegt keine Ehrlichkeit. Das Abschwächen wäre sogar ehrlich, wenn er die kühne Aussage dauerhaft aufgäbe. Problematisch ist, dass er sie danach wieder vertritt."},{"option":2,"text":"Seine Aussage zur Weiterbildung ist tatsächlich wahr, und das ist nicht das Problem. Wahres zu sagen tarnt aber nicht zwangsläufig etwas Falsches. Entscheidend ist, wie die Aussage hier benutzt wird: als vorübergehender Rückzug, auf den die alte Behauptung folgt."},{"option":3,"text":"Angekündigt oder offen getrennt wird hier nichts: Er behauptet nur, er habe nie mehr gesagt, als dass Weiterbildung sinnvoll sei. Das Problem ist, dass er danach zur starken Aussage zurückkehrt, ohne sie je belegt zu haben."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2"},{"id":"qx-d1-046","clusterId":"D","werkstueckRef":"D.3.2","stufe":4,"question":"Was ist an diesem Gesprächsverlauf aus Sicht der Prüfbarkeit das eigentliche Problem?","scenario":"In einer Diskussion behauptet jemand: „Unsere Methode heilt jede Krankheit, auch Krebs.“ Du fragst nach kontrollierten Studien. Er antwortet: „Ich meine ja nur, dass eine positive Einstellung wichtig für den Heilungsprozess ist.“ Du stimmst zu, und prompt sagt er wieder: „Siehst du, deshalb heilt unsere Methode eben jede Krankheit.“","options":["Die starke Behauptung wird bei Kritik so lange durch eine harmlose ersetzt, dass sie nie widerlegt werden kann, und kehrt danach unverändert zurück.","Die starke Behauptung wird präzise formuliert und bleibt prüfbar, weil er sich lediglich ein späteres Neuverteidigen vorbehält.","Die starke Behauptung wird dauerhaft aufgegeben, sodass nur noch die harmlose Aussage zur Debatte steht und alles geklärt ist.","Die harmlose Aussage stützt indirekt auch die starke Behauptung, weil beide aus derselben Überzeugung stammen und daher gleich glaubwürdig sind."],"correctIndex":0,"explanation":"Eine Behauptung ist nur dann prüfbar, wenn man sagen kann, was sie ausschließt und woran sie scheitern würde. Hier geschieht das Gegenteil: Sobald es um Belege geht, verschwindet die kühne These und eine harmlose Aussage tritt an ihre Stelle, die kaum jemand bestreitet. Danach taucht die kühne These unverändert wieder auf, als wäre nichts gewesen. So wird sie nie wirklich getestet und kann nie scheitern, obwohl sie nie bestanden hat. Dass die harmlose Aussage stimmt, sagt nichts über die starke aus: Dass eine positive Einstellung beim Genesen helfen kann, belegt nicht, dass eine Methode Krebs heilt. Wirksam ist, die Debatte zur ursprünglichen Behauptung zurückzuführen: „Der gemäßigten Aussage stimme ich zu. Stehst du noch zu deiner ersten, viel stärkeren Behauptung? Denn sie war mein Kritikpunkt.“ Erst dann muss er sich entscheiden: belegen oder zurücknehmen.","coreRule":"⚡ Wer seine kühne These bei Kritik unsichtbar macht, entzieht sie der Widerlegung. Hake bei der ursprünglichen Behauptung nach, nicht beim Rückzugsort.","beleg":"Werkstück D.3.2 (Verbindungen: Falsifizierbarkeit; Anti-Denkmuster)","status":"entwurf","kurz":"Wird die kühne These bei Kritik durch eine harmlose ersetzt und danach unverändert wiederholt, wird sie nie wirklich getestet. Dass die harmlose Aussage stimmt, sagt nichts darüber, ob die starke trägt.","prueffrage":"Woran müsste die Behauptung „heilt jede Krankheit“ scheitern können, und bekommt sie im Gespräch überhaupt eine Gelegenheit dazu?","rueckmeldung":[{"option":1,"text":"Sich vorzubehalten, eine Behauptung später erneut zu verteidigen, kann legitim sein. Hier wird sie aber genau dann ersetzt, wenn Belege gefragt sind, und kehrt danach unverändert zurück. So bekommt sie nie eine Gelegenheit zu scheitern."},{"option":2,"text":"Eine Rücknahme würde das Problem tatsächlich lösen. Im Gespräch geschieht aber das Gegenteil: Die starke Behauptung kehrt gleich danach unverändert zurück, die Frage nach Belegen bleibt also offen."},{"option":3,"text":"Beide Aussagen mögen derselben Überzeugung entspringen, aber Glaubwürdigkeit überträgt sich so nicht. Dass eine positive Einstellung beim Genesen helfen kann, lässt offen, ob eine bestimmte Methode Krebs heilt."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2"}]`);export{t as n,n as t};